/**
 * Clone stamp operations for FreetoShop.
 *
 * Implements Photoshop-style clone stamp tool that samples from a source layer
 * and paints onto a destination layer, supporting aligned/unaligned modes,
 * transformed layers, and selection clipping.
 */

import {
  createPixelLayer,
  findLayer,
  findLayerWorldTransform,
  type ImageDocument,
  type PixelLayer,
  type PixelPatch,
  type SelectionMask,
  type LayerTransform,
  type BrushPoint,
} from '@freetoshop/core-document';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import { paintStroke, type BrushOptions, compositeSourceOver, applyTransform, invertTransform, unionBounds, emptyPatch } from './index.js';

export interface CloneSource {
  /** The layer ID to clone from. */
  readonly sourceLayerId: string;
  /** Document-space position of the clone source origin. */
  readonly sourcePoint: { x: number; y: number };
  /** World transform of the source layer at the time the source was set. */
  readonly sourceLayerWorldTransform: LayerTransform;
  /** When true, the offset between source and destination is preserved across the stroke. */
  readonly aligned: boolean;
  /** Optional fixed offset from source to destination in document pixels. */
  readonly offset: { x: number; y: number } | null;
}

export interface CloneStampOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly source: CloneSource;
}

export interface CloneStampCommand {
  readonly label: string;
  readonly execute: (document: ImageDocument) => ImageDocument;
}

/**
 * Computes the source document point for a given destination point in aligned mode.
 * In aligned mode, the offset between the initial source point and destination point
 * is preserved throughout the stroke.
 */
function computeAlignedSourcePoint(
  destDocPoint: { x: number; y: number },
  initialSrcPoint: { x: number; y: number },
  initialDestPoint: { x: number; y: number },
  offset: { x: number; y: number } | null,
): { x: number; y: number } {
  // Calculate the offset between initial source and destination
  const baseOffsetX = destDocPoint.x - initialDestPoint.x;
  const baseOffsetY = destDocPoint.y - initialDestPoint.y;

  // Source point = source origin + offset from destination movement
  let sourceX = initialSrcPoint.x + baseOffsetX;
  let sourceY = initialSrcPoint.y + baseOffsetY;

  // Apply any additional fixed offset
  if (offset !== null) {
    sourceX += offset.x;
    sourceY += offset.y;
  }

  return { x: sourceX, y: sourceY };
}

/**
 * Computes the source document point for a given destination point in unaligned mode.
 * In unaligned mode, always samples from the original source point (plus any offset).
 */
function computeUnalignedSourcePoint(
  sourcePoint: { x: number; y: number },
  offset: { x: number; y: number } | null,
): { x: number; y: number } {
  if (offset !== null) {
    return { x: sourcePoint.x + offset.x, y: sourcePoint.y + offset.y };
  }
  return { ...sourcePoint };
}

/**
 * Samples a single pixel from the source layer at the given document-space point.
 */
function sampleSourcePixel(
  sourceLayer: PixelLayer,
  sourceDocPoint: { x: number; y: number },
  sourceWorldTransform: LayerTransform,
): [number, number, number, number] | null {
  // Convert document point to source layer-local coordinates
  const localSrc = applyInverseTransform(sourceWorldTransform, sourceDocPoint.x, sourceDocPoint.y);

  // Check bounds
  if (localSrc.x < 0 || localSrc.y < 0 || localSrc.x >= sourceLayer.width || localSrc.y >= sourceLayer.height) {
    return null;
  }

  // Sample the source pixel (nearest neighbor)
  const srcX = Math.round(localSrc.x);
  const srcY = Math.round(localSrc.y);
  const sourcePixels = sourceLayer.pixelStore.read({
    x: srcX,
    y: srcY,
    width: 1,
    height: 1,
  });

  return [
    sourcePixels[0],
    sourcePixels[1],
    sourcePixels[2],
    sourcePixels[3],
  ];
}

/**
 * Paints a clone stamp stroke, sampling pixels from a source layer and writing them
 * to a destination layer. Returns the smallest layer-local patch containing changed pixels.
 *
 * In aligned mode, the offset between the source position and each destination point
 * is preserved throughout the stroke. In unaligned mode, each dab samples from the
 * same source position.
 */
export function paintCloneStamp(
  destinationLayer: PixelLayer,
  sourceLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  destinationWorldTransform?: LayerTransform,
  sourceWorldTransform?: LayerTransform,
): PixelPatch {
  const effectiveDestinationTransform = destinationWorldTransform ?? destinationLayer.transform;
  const effectiveSourceTransform = sourceWorldTransform ?? sourceLayer.transform;

  // Validate inputs
  if (!destinationLayer || !sourceLayer) {
    throw new RangeError('Both destination and source layers are required');
  }

  if (points.length === 0) {
    throw new RangeError('Stroke must contain at least one point');
  }

  const { size, hardness, opacity, source } = options;

  if (size <= 0) {
    throw new RangeError('Brush size must be greater than 0');
  }

  if (hardness < 0 || hardness > 1) {
    throw new RangeError('Hardness must be between 0 and 1');
  }

  if (opacity < 0 || opacity > 1) {
    throw new RangeError('Opacity must be between 0 and 1');
  }

  if (!source.sourceLayerId) {
    throw new RangeError('Clone source layer ID is required');
  }

  const radius = size / 2;

  // Build dabs by interpolating points (same as paintStroke)
  const spacing = Math.max(0.25, radius * 0.5);
  const dabs: Array<{ x: number; y: number; pressure: number }> = [];

  const first = points[0];
  dabs.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });

  for (let i = 1; i < points.length; i++) {
    const start = points[i - 1];
    const end = points[i];
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const steps = Math.max(1, Math.ceil(distance / spacing));
    for (let step = 1; step <= steps; step++) {
      const progress = step / steps;
      dabs.push({
        x: start.x + (end.x - start.x) * progress,
        y: start.y + (end.y - start.y) * progress,
        pressure: (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
      });
    }
  }

  // Compute stroke bounds in destination layer local space
  let strokeBounds: { left: number; top: number; right: number; bottom: number } | null = null;

  for (const dab of dabs) {
    // Convert destination document point to layer-local coordinates
    const localDest = applyInverseTransform(effectiveDestinationTransform, dab.x, dab.y);

    // Accumulate stroke bounds (destination layer local space)
    if (!strokeBounds) {
      strokeBounds = {
        left: Math.floor(localDest.x - radius),
        top: Math.floor(localDest.y - radius),
        right: Math.ceil(localDest.x + radius),
        bottom: Math.ceil(localDest.y + radius),
      };
    } else {
      strokeBounds.left = Math.min(strokeBounds.left, Math.floor(localDest.x - radius));
      strokeBounds.top = Math.min(strokeBounds.top, Math.floor(localDest.y - radius));
      strokeBounds.right = Math.max(strokeBounds.right, Math.ceil(localDest.x + radius));
      strokeBounds.bottom = Math.max(strokeBounds.bottom, Math.ceil(localDest.y + radius));
    }
  }

  if (!strokeBounds) {
    return emptyPatch();
  }

  // Clip to layer bounds
  strokeBounds.left = Math.max(0, strokeBounds.left);
  strokeBounds.top = Math.max(0, strokeBounds.top);
  strokeBounds.right = Math.min(destinationLayer.width - 1, strokeBounds.right);
  strokeBounds.bottom = Math.min(destinationLayer.height - 1, strokeBounds.bottom);

  if (strokeBounds.left > strokeBounds.right || strokeBounds.top > strokeBounds.bottom) {
    return emptyPatch();
  }

  // Read destination region
  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
  const pixels = new Uint8ClampedArray(destinationLayer.pixelStore.read({
    x: strokeBounds.left,
    y: strokeBounds.top,
    width: regionWidth,
    height: regionHeight,
  }));

  // Process each dab
  let changedBounds: { left: number; top: number; right: number; bottom: number } | null = null;
  const initialDestPoint = dabs[0];

  for (const dab of dabs) {
    // Compute source document point based on aligned/unaligned mode
    let sourceDocPoint: { x: number; y: number };

    if (source.aligned) {
      // Aligned mode: preserve offset from initial source to initial destination
      sourceDocPoint = computeAlignedSourcePoint(
        dab,
        source.sourcePoint,
        initialDestPoint,
        source.offset,
      );
    } else {
      // Unaligned mode: always sample from original source point + offset
      sourceDocPoint = computeUnalignedSourcePoint(source.sourcePoint, source.offset);
    }

    // Convert to layer-local coordinates
    const localDest = applyInverseTransform(effectiveDestinationTransform, dab.x, dab.y);
    const localSrc = applyInverseTransform(effectiveSourceTransform, sourceDocPoint.x, sourceDocPoint.y);

    // Check source bounds
    if (localSrc.x < 0 || localSrc.y < 0 || localSrc.x >= sourceLayer.width || localSrc.y >= sourceLayer.height) {
      continue;
    }

    // Sample source color at this dab's source location
    const srcX = Math.round(localSrc.x);
    const srcY = Math.round(localSrc.y);
    const sourcePixels = sourceLayer.pixelStore.read({
      x: srcX,
      y: srcY,
      width: 1,
      height: 1,
    });
    const sampledColor: [number, number, number, number] = [
      sourcePixels[0],
      sourcePixels[1],
      sourcePixels[2],
      sourcePixels[3],
    ];

    // Paint this dab using the sampled color
    const bounds = paintSingleDab(
      pixels,
      strokeBounds,
      regionWidth,
      regionHeight,
      localDest,
      radius,
      hardness,
      opacity,
      dab.pressure,
      sampledColor,
      selection,
      effectiveDestinationTransform,
    );

    if (bounds) {
      changedBounds = unionBounds(changedBounds, bounds);
    }
  }

  if (!changedBounds) {
    return emptyPatch();
  }

  // Extract the changed region from the working pixels
  const patchLeft = Math.max(strokeBounds.left, changedBounds.left);
  const patchTop = Math.max(strokeBounds.top, changedBounds.top);
  const patchRight = Math.min(strokeBounds.left + regionWidth - 1, changedBounds.right);
  const patchBottom = Math.min(strokeBounds.top + regionHeight - 1, changedBounds.bottom);

  const patchWidth = patchRight - patchLeft + 1;
  const patchHeight = patchBottom - patchTop + 1;
  const patchPixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);

  for (let y = patchTop; y <= patchBottom; y++) {
    for (let x = patchLeft; x <= patchRight; x++) {
      const srcOffset = ((y - strokeBounds.top) * regionWidth + (x - strokeBounds.left)) * 4;
      const dstOffset = ((y - patchTop) * patchWidth + (x - patchLeft)) * 4;
      patchPixels[dstOffset] = pixels[srcOffset];
      patchPixels[dstOffset + 1] = pixels[srcOffset + 1];
      patchPixels[dstOffset + 2] = pixels[srcOffset + 2];
      patchPixels[dstOffset + 3] = pixels[srcOffset + 3];
    }
  }

  return {
    x: patchLeft,
    y: patchTop,
    width: patchWidth,
    height: patchHeight,
    pixels: patchPixels,
  };
}

interface DabBounds {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

function paintSingleDab(
  pixels: Uint8ClampedArray,
  strokeBounds: { left: number; top: number; right: number; bottom: number },
  regionWidth: number,
  regionHeight: number,
  localDest: { x: number; y: number },
  radius: number,
  hardness: number,
  opacity: number,
  pressure: number,
  color: [number, number, number, number],
  selection: SelectionMask | null,
  worldTransform: LayerTransform,
): DabBounds | null {
  let changedBounds: DabBounds | null = null;

  // Iterate over pixels in the dab's influence region
  const startX = Math.max(strokeBounds.left, Math.floor(localDest.x - radius));
  const startY = Math.max(strokeBounds.top, Math.floor(localDest.y - radius));
  const endX = Math.min(strokeBounds.left + regionWidth - 1, Math.ceil(localDest.x + radius));
  const endY = Math.min(strokeBounds.top + regionHeight - 1, Math.ceil(localDest.y + radius));

  for (let y = startY; y <= endY; y++) {
    for (let x = startX; x <= endX; x++) {
      // Convert to document space
      const docPoint = applyTransform(worldTransform, x, y);

      // Calculate distance from dab center in document space
      const dx = docPoint.x - localDest.x;
      const dy = docPoint.y - localDest.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance > radius) continue;

      // Calculate falloff based on hardness
      let falloff = 1;
      if (hardness < 1) {
        const hardRadius = radius * hardness;
        if (distance > hardRadius) {
          falloff = 1 - (distance - hardRadius) / (radius - hardRadius);
        }
      }

      // Check selection
      let selected = 1;
      if (selection) {
        const selX = Math.round(docPoint.x);
        const selY = Math.round(docPoint.y);
        if (selX >= 0 && selX < selection.width && selY >= 0 && selY < selection.height) {
          const coverage = selection.coverageStore.read({
            x: selX,
            y: selY,
            width: 1,
            height: 1,
          })[0];
          selected = coverage / 255;
        } else {
          selected = 0;
        }
      }

      const strength = falloff * opacity * pressure * selected;
      if (strength <= 0) continue;

      // Apply source-over compositing
      const pixelOffset = ((y - strokeBounds.top) * regionWidth + (x - strokeBounds.left)) * 4;
      compositeSourceOver(pixels, pixelOffset, color, strength);

      // Track changed bounds
      if (!changedBounds) {
        changedBounds = { left: x, top: y, right: x, bottom: y };
      } else {
        changedBounds.left = Math.min(changedBounds.left, x);
        changedBounds.top = Math.min(changedBounds.top, y);
        changedBounds.right = Math.max(changedBounds.right, x);
        changedBounds.bottom = Math.max(changedBounds.bottom, y);
      }
    }
  }

  return changedBounds;
}

/**
 * Command that applies a clone stamp stroke as an atomic undoable operation.
 */
export function createCloneStampCommand(
  destinationLayerId: string,
  sourceLayerId: string,
  initialDestPoint: { x: number; y: number },
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
): CloneStampCommand {
  return {
    label: 'Clone Stamp',
    execute: (document: ImageDocument) => {
      const destinationLayer = findLayer(document, destinationLayerId);
      const sourceLayer = findLayer(document, sourceLayerId);

      if (!destinationLayer || !sourceLayer) {
        throw new RangeError('Layer not found');
      }

      if (destinationLayer.kind !== 'pixel' || sourceLayer.kind !== 'pixel') {
        throw new RangeError('Both layers must be pixel layers');
      }

      // Get world transforms for both layers
      const destWorldTransform = findLayerWorldTransform(document, destinationLayerId);
      const sourceWorldTransform = findLayerWorldTransform(document, sourceLayerId);

      // Perform the clone stamp operation
      const patch = paintCloneStamp(
        destinationLayer,
        sourceLayer,
        points,
        options,
        selection,
        destWorldTransform,
        sourceWorldTransform,
      );

      // Apply the patch if there are changes
      if (patch.width > 0 && patch.height > 0) {
        const updatedDestinationLayer = {
          ...destinationLayer,
          pixelStore: destinationLayer.pixelStore.write({
            x: patch.x,
            y: patch.y,
            width: patch.width,
            height: patch.height,
            pixels: new Uint8ClampedArray(patch.pixels),
          }).store,
        };

        return {
          ...document,
          layers: document.layers.map((layer) =>
            layer.id === destinationLayerId ? updatedDestinationLayer : layer,
          ),
        };
      }

      return document;
    },
  };
}

/**
 * Clone stamp operations for FreetoShop.
 *
 * Implements Photoshop-style clone stamp tool that samples from a source layer
 * and paints onto a destination layer, supporting aligned/unaligned modes,
 * transformed layers, and selection clipping.
 */

import {
  createPixelLayer,
  findLayer,
  findLayerWorldTransform,
  type ImageDocument,
  type PixelLayer,
  type PixelPatch,
  type SelectionMask,
  type LayerTransform,
  type BrushPoint,
} from '@freetoshop/core-document';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import { paintStroke, type BrushOptions, compositeSourceOver, applyTransform, invertTransform, unionBounds, emptyPatch } from './index.js';

export interface CloneSource {
  /** The layer ID to clone from. */
  readonly sourceLayerId: string;
  /** Document-space position of the clone source origin. */
  readonly sourcePoint: { x: number; y: number };
  /** World transform of the source layer at the time the source was set. */
  readonly sourceLayerWorldTransform: LayerTransform;
  /** When true, the offset between source and destination is preserved across the stroke. */
  readonly aligned: boolean;
  /** Optional fixed offset from source to destination in document pixels. */
  readonly offset: { x: number; y: number } | null;
}

export interface CloneStampOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly source: CloneSource;
}

export interface CloneStampCommand {
  readonly label: string;
  readonly execute: (document: ImageDocument) => ImageDocument;
}

/**
 * Computes the source document point for a given destination point in aligned mode.
 * In aligned mode, the offset between the initial source point and destination point
 * is preserved throughout the stroke.
 */
function computeAlignedSourcePoint(
  destDocPoint: { x: number; y: number },
  initialSrcPoint: { x: number; y: number },
  initialDestPoint: { x: number; y: number },
  offset: { x: number; y: number } | null,
): { x: number; y: number } {
  // Calculate the offset between initial source and destination
  const baseOffsetX = destDocPoint.x - initialDestPoint.x;
  const baseOffsetY = destDocPoint.y - initialDestPoint.y;

  // Source point = source origin + offset from destination movement
  let sourceX = initialSrcPoint.x + baseOffsetX;
  let sourceY = initialSrcPoint.y + baseOffsetY;

  // Apply any additional fixed offset
  if (offset !== null) {
    sourceX += offset.x;
    sourceY += offset.y;
  }

  return { x: sourceX, y: sourceY };
}

/**
 * Computes the source document point for a given destination point in unaligned mode.
 * In unaligned mode, always samples from the original source point (plus any offset).
 */
function computeUnalignedSourcePoint(
  sourcePoint: { x: number; y: number },
  offset: { x: number; y: number } | null,
): { x: number; y: number } {
  if (offset !== null) {
    return { x: sourcePoint.x + offset.x, y: sourcePoint.y + offset.y };
  }
  return { ...sourcePoint };
}

/**
 * Samples a single pixel from the source layer at the given document-space point.
 */
function sampleSourcePixel(
  sourceLayer: PixelLayer,
  sourceDocPoint: { x: number; y: number },
  sourceWorldTransform: LayerTransform,
): [number, number, number, number] | null {
  // Convert document point to source layer-local coordinates
  const localSrc = applyInverseTransform(sourceWorldTransform, sourceDocPoint.x, sourceDocPoint.y);

  // Check bounds
  if (localSrc.x < 0 || localSrc.y < 0 || localSrc.x >= sourceLayer.width || localSrc.y >= sourceLayer.height) {
    return null;
  }

  // Sample the source pixel (nearest neighbor)
  const srcX = Math.round(localSrc.x);
  const srcY = Math.round(localSrc.y);
  const sourcePixels = sourceLayer.pixelStore.read({
    x: srcX,
    y: srcY,
    width: 1,
    height: 1,
  });

  return [
    sourcePixels[0],
    sourcePixels[1],
    sourcePixels[2],
    sourcePixels[3],
  ];
}

/**
 * Paints a clone stamp stroke, sampling pixels from a source layer and writing them
 * to a destination layer. Returns the smallest layer-local patch containing changed pixels.
 *
 * In aligned mode, the offset between the source position and each destination point
 * is preserved throughout the stroke. In unaligned mode, each dab samples from the
 * same source position.
 */
export function paintCloneStamp(
  destinationLayer: PixelLayer,
  sourceLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  destinationWorldTransform?: LayerTransform,
  sourceWorldTransform?: LayerTransform,
): PixelPatch {
  const effectiveDestinationTransform = destinationWorldTransform ?? destinationLayer.transform;
  const effectiveSourceTransform = sourceWorldTransform ?? sourceLayer.transform;

  // Validate inputs
  if (!destinationLayer || !sourceLayer) {
    throw new RangeError('Both destination and source layers are required');
  }

  if (points.length === 0) {
    throw new RangeError('Stroke must contain at least one point');
  }

  const { size, hardness, opacity, source } = options;

  if (size <= 0) {
    throw new RangeError('Brush size must be greater than 0');
  }

  if (hardness < 0 || hardness > 1) {
    throw new RangeError('Hardness must be between 0 and 1');
  }

  if (opacity < 0 || opacity > 1) {
    throw new RangeError('Opacity must be between 0 and 1');
  }

  if (!source.sourceLayerId) {
    throw new RangeError('Clone source layer ID is required');
  }

  const radius = size / 2;

  // Build dabs by interpolating points (same as paintStroke)
  const spacing = Math.max(0.25, radius * 0.5);
  const dabs: Array<{ x: number; y: number; pressure: number }> = [];

  const first = points[0];
  dabs.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });

  for (let i = 1; i < points.length; i++) {
    const start = points[i - 1];
    const end = points[i];
    const distance = Math.hypot(end.x - start.x, end.y - start.y);
    const steps = Math.max(1, Math.ceil(distance / spacing));
    for (let step = 1; step <= steps; step++) {
      const progress = step / steps;
      dabs.push({
        x: start.x + (end.x - start.x) * progress,
        y: start.y + (end.y - start.y) * progress,
        pressure: (start.pressure ?? 1) + ((end.pressure ?? 1) - (start.pressure ?? 1)) * progress,
      });
    }
  }

  // Compute stroke bounds in destination layer local space
  let strokeBounds: { left: number; top: number; right: number; bottom: number } | null = null;

  for (const dab of dabs) {
    // Convert destination document point to layer-local coordinates
    const localDest = applyInverseTransform(effectiveDestinationTransform, dab.x, dab.y);

    // Accumulate stroke bounds (destination layer local space)
    if (!strokeBounds) {
      strokeBounds = {
        left: Math.floor(localDest.x - radius),
        top: Math.floor(localDest.y - radius),
        right: Math.ceil(localDest.x + radius),
        bottom: Math.ceil(localDest.y + radius),
      };
    } else {
      strokeBounds.left = Math.min(strokeBounds.left, Math.floor(localDest.x - radius));
      strokeBounds.top = Math.min(strokeBounds.top, Math.floor(localDest.y - radius));
      strokeBounds.right = Math.max(strokeBounds.right, Math.ceil(localDest.x + radius));
      strokeBounds.bottom = Math.max(strokeBounds.bottom, Math.ceil(localDest.y + radius));
    }
  }

  if (!strokeBounds) {
    return emptyPatch();
  }

  // Clip to layer bounds
  strokeBounds.left = Math.max(0, strokeBounds.left);
  strokeBounds.top = Math.max(0, strokeBounds.top);
  strokeBounds.right = Math.min(destinationLayer.width - 1, strokeBounds.right);
  strokeBounds.bottom = Math.min(destinationLayer.height - 1, strokeBounds.bottom);

  if (strokeBounds.left > strokeBounds.right || strokeBounds.top > strokeBounds.bottom) {
    return emptyPatch();
  }

  // Read destination region
  const regionWidth = strokeBounds.right - strokeBounds.left + 1;
  const regionHeight = strokeBounds.bottom - strokeBounds.top + 1;
  const pixels = new Uint8ClampedArray(destinationLayer.pixelStore.read({
    x: strokeBounds.left,
    y: strokeBounds.top,
    width: regionWidth,
    height: regionHeight,
  }));

  // Process each dab
  let changedBounds: { left: number; top: number; right: number; bottom: number } | null = null;
  const initialDestPoint = dabs[0];

  for (const dab of dabs) {
    // Compute source document point based on aligned/unaligned mode
    let sourceDocPoint: { x: number; y: number };

    if (source.aligned) {
      // Aligned mode: preserve offset from initial source to initial destination
      sourceDocPoint = computeAlignedSourcePoint(
        dab,
        source.sourcePoint,
        initialDestPoint,
        source.offset,
      );
    } else {
      // Unaligned mode: always sample from original source point + offset
      sourceDocPoint = computeUnalignedSourcePoint(source.sourcePoint, source.offset);
    }

    // Convert to layer-local coordinates
    const localDest = applyInverseTransform(effectiveDestinationTransform, dab.x, dab.y);
    const localSrc = applyInverseTransform(effectiveSourceTransform, sourceDocPoint.x, sourceDocPoint.y);

    // Check source bounds
    if (localSrc.x < 0 || localSrc.y < 0 || localSrc.x >= sourceLayer.width || localSrc.y >= sourceLayer.height) {
      continue;
    }

    // Sample source color at this dab's source location
    const srcX = Math.round(localSrc.x);
    const srcY = Math.round(localSrc.y);
    const sourcePixels = sourceLayer.pixelStore.read({
      x: srcX,
      y: srcY,
      width: 1,
      height: 1,
    });
    const sampledColor: [number, number, number, number] = [
      sourcePixels[0],
      sourcePixels[1],
      sourcePixels[2],
      sourcePixels[3],
    ];

    // Paint this dab using the sampled color
    const bounds = paintSingleDab(
      pixels,
      strokeBounds,
      regionWidth,
      regionHeight,
      localDest,
      radius,
      hardness,
      opacity,
      dab.pressure,
      sampledColor,
      selection,
      effectiveDestinationTransform,
    );

    if (bounds) {
      changedBounds = unionBounds(changedBounds, bounds);
    }
  }

  if (!changedBounds) {
    return emptyPatch();
  }

  // Extract the changed region from the working pixels
  const patchLeft = Math.max(strokeBounds.left, changedBounds.left);
  const patchTop = Math.max(strokeBounds.top, changedBounds.top);
  const patchRight = Math.min(strokeBounds.left + regionWidth - 1, changedBounds.right);
  const patchBottom = Math.min(strokeBounds.top + regionHeight - 1, changedBounds.bottom);

  const patchWidth = patchRight - patchLeft + 1;
  const patchHeight = patchBottom - patchTop + 1;
  const patchPixels = new Uint8ClampedArray(patchWidth * patchHeight * 4);

  for (let y = patchTop; y <= patchBottom; y++) {
    for (let x = patchLeft; x <= patchRight; x++) {
      const srcOffset = ((y - strokeBounds.top) * regionWidth + (x - strokeBounds.left)) * 4;
      const dstOffset = ((y - patchTop) * patchWidth + (x - patchLeft)) * 4;
      patchPixels[dstOffset] = pixels[srcOffset];
      patchPixels[dstOffset + 1] = pixels[srcOffset + 1];
      patchPixels[dstOffset + 2] = pixels[srcOffset + 2];
      patchPixels[dstOffset + 3] = pixels[srcOffset + 3];
    }
  }

  return {
    x: patchLeft,
    y: patchTop,
    width: patchWidth,
    height: patchHeight,
    pixels: patchPixels,
  };
}

interface DabBounds {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

function paintSingleDab(
  pixels: Uint8ClampedArray,
  strokeBounds: { left: number; top: number; right: number; bottom: number },
  regionWidth: number,
  regionHeight: number,
  localDest: { x: number; y: number },
  radius: number,
  hardness: number,
  opacity: number,
  pressure: number,
  color: [number, number, number, number],
  selection: SelectionMask | null,
  worldTransform: LayerTransform,
): DabBounds | null {
  let changedBounds: DabBounds | null = null;

  // Iterate over pixels in the dab's influence region
  const startX = Math.max(strokeBounds.left, Math.floor(localDest.x - radius));
  const startY = Math.max(strokeBounds.top, Math.floor(localDest.y - radius));
  const endX = Math.min(strokeBounds.left + regionWidth - 1, Math.ceil(localDest.x + radius));
  const endY = Math.min(strokeBounds.top + regionHeight - 1, Math.ceil(localDest.y + radius));

  for (let y = startY; y <= endY; y++) {
    for (let x = startX; x <= endX; x++) {
      // Convert to document space
      const docPoint = applyTransform(worldTransform, x, y);

      // Calculate distance from dab center in document space
      const dx = docPoint.x - localDest.x;
      const dy = docPoint.y - localDest.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance > radius) continue;

      // Calculate falloff based on hardness
      let falloff = 1;
      if (hardness < 1) {
        const hardRadius = radius * hardness;
        if (distance > hardRadius) {
          falloff = 1 - (distance - hardRadius) / (radius - hardRadius);
        }
      }

      // Check selection
      let selected = 1;
      if (selection) {
        const selX = Math.round(docPoint.x);
        const selY = Math.round(docPoint.y);
        if (selX >= 0 && selX < selection.width && selY >= 0 && selY < selection.height) {
          const coverage = selection.coverageStore.read({
            x: selX,
            y: selY,
            width: 1,
            height: 1,
          })[0];
          selected = coverage / 255;
        } else {
          selected = 0;
        }
      }

      const strength = falloff * opacity * pressure * selected;
      if (strength <= 0) continue;

      // Apply source-over compositing
      const pixelOffset = ((y - strokeBounds.top) * regionWidth + (x - strokeBounds.left)) * 4;
      compositeSourceOver(pixels, pixelOffset, color, strength);

      // Track changed bounds
      if (!changedBounds) {
        changedBounds = { left: x, top: y, right: x, bottom: y };
      } else {
        changedBounds.left = Math.min(changedBounds.left, x);
        changedBounds.top = Math.min(changedBounds.top, y);
        changedBounds.right = Math.max(changedBounds.right, x);
        changedBounds.bottom = Math.max(changedBounds.bottom, y);
      }
    }
  }

  return changedBounds;
}

/**
 * Command that applies a clone stamp stroke as an atomic undoable operation.
 */
export function createCloneStampCommand(
  destinationLayerId: string,
  sourceLayerId: string,
  initialDestPoint: { x: number; y: number },
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
): CloneStampCommand {
  return {
    label: 'Clone Stamp',
    execute: (document: ImageDocument) => {
      const destinationLayer = findLayer(document, destinationLayerId);
      const sourceLayer = findLayer(document, sourceLayerId);

      if (!destinationLayer || !sourceLayer) {
        throw new RangeError('Layer not found');
      }

      if (destinationLayer.kind !== 'pixel' || sourceLayer.kind !== 'pixel') {
        throw new RangeError('Both layers must be pixel layers');
      }

      // Get world transforms for both layers
      const destWorldTransform = findLayerWorldTransform(document, destinationLayerId);
      const sourceWorldTransform = findLayerWorldTransform(document, sourceLayerId);

      // Perform the clone stamp operation
      const patch = paintCloneStamp(
        destinationLayer,
        sourceLayer,
        points,
        options,
        selection,
        destWorldTransform,
        sourceWorldTransform,
      );

      // Apply the patch if there are changes
      if (patch.width > 0 && patch.height > 0) {
        const updatedDestinationLayer = {
          ...destinationLayer,
          pixelStore: destinationLayer.pixelStore.write({
            x: patch.x,
            y: patch.y,
            width: patch.width,
            height: patch.height,
            pixels: new Uint8ClampedArray(patch.pixels),
          }).store,
        };

        return {
          ...document,
          layers: document.layers.map((layer) =>
            layer.id === destinationLayerId ? updatedDestinationLayer : layer,
          ),
        };
      }

      return document;
    },
  };
}

