    for (let x = patchLeft; x <= patchRight; x++) {
      const srcOffset = ((y - strokeBounds.top) * regionWidth + (x - strokeBounds.left)) * 4;
      const dstOffset = ((y - patchTop) * patchWidth + (x - patchLeft)) * 4;
      patchPixels[dstOffset] = pixels[srcOffset];
      patchPixels[dstOffset + 1] = pixels[srcOffset + 1];
      patchPixels[dstOffset + 2] = pixels[srcOffset + 2];
      patchPixels[dstOffset + 3] = pixels[srcOffset + 3];
    }
  }

  return {
    x: patchLeft,
    y: patchTop,
    width: patchWidth,
    height: patchHeight,
    pixels: patchPixels,
  };
}

interface DabBounds {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

function paintSingleDab(
  pixels: Uint8ClampedArray,
  strokeBounds: { left: number; top: number; right: number; bottom: number },
  regionWidth: number,
  regionHeight: number,
  localDest: { x: number; y: number },
  radius: number,
  hardness: number,
  opacity: number,
  pressure: number,
  color: [number, number, number, number],
  selection: SelectionMask | null,
  worldTransform: LayerTransform,
): DabBounds | null {
  let changedBounds: DabBounds | null = null;

  // Iterate over pixels in the dab's influence region
  const startX = Math.max(strokeBounds.left, Math.floor(localDest.x - radius));
  const startY = Math.max(strokeBounds.top, Math.floor(localDest.y - radius));
  const endX = Math.min(strokeBounds.left + regionWidth - 1, Math.ceil(localDest.x + radius));
  const endY = Math.min(strokeBounds.top + regionHeight - 1, Math.ceil(localDest.y + radius));

  for (let y = startY; y <= endY; y++) {
    for (let x = startX; x <= endX; x++) {
      // Convert to document space
      const docPoint = applyTransform(worldTransform, x, y);

      // Calculate distance from dab center in document space
      const dx = docPoint.x - localDest.x;
      const dy = docPoint.y - localDest.y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance > radius) continue;

      // Calculate falloff based on hardness
      let falloff = 1;
      if (hardness < 1) {
        const hardRadius = radius * hardness;
        if (distance > hardRadius) {
          falloff = 1 - (distance - hardRadius) / (radius - hardRadius);
        }
      }

      // Check selection
      let selected = 1;
      if (selection) {
        const selX = Math.round(docPoint.x);
        const selY = Math.round(docPoint.y);
        if (selX >= 0 && selX < selection.width && selY >= 0 && selY < selection.height) {
          const coverage = selection.coverageStore.read({
            x: selX,
            y: selY,
            width: 1,
            height: 1,
          })[0];
          selected = coverage / 255;
        } else {
          selected = 0;
        }
      }

      const strength = falloff * opacity * pressure * selected;
      if (strength <= 0) continue;

      // Apply source-over compositing
      const pixelOffset = ((y - strokeBounds.top) * regionWidth + (x - strokeBounds.left)) * 4;
      compositeSourceOver(pixels, pixelOffset, color, strength);

      // Track changed bounds
      if (!changedBounds) {
        changedBounds = { left: x, top: y, right: x, bottom: y };
      } else {
        changedBounds.left = Math.min(changedBounds.left, x);
        changedBounds.top = Math.min(changedBounds.top, y);
        changedBounds.right = Math.max(changedBounds.right, x);
        changedBounds.bottom = Math.max(changedBounds.bottom, y);
      }
    }
  }

  return changedBounds;
}

/**
 * Command that applies a clone stamp stroke as an atomic undoable operation.
 */
export function createCloneStampCommand(
  destinationLayerId: string,
  sourceLayerId: string,
  initialDestPoint: { x: number; y: number },
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
): CloneStampCommand {
  return {
    label: 'Clone Stamp',
    execute: (document: ImageDocument) => {
      const destinationLayer = findLayer(document, destinationLayerId);
      const sourceLayer = findLayer(document, sourceLayerId);

      if (!destinationLayer || !sourceLayer) {
        throw new RangeError('Layer not found');
      }

      if (destinationLayer.kind !== 'pixel' || sourceLayer.kind !== 'pixel') {
        throw new RangeError('Both layers must be pixel layers');
      }

      // Get world transforms for both layers
      const destWorldTransform = findLayerWorldTransform(document, destinationLayerId);
      const sourceWorldTransform = findLayerWorldTransform(document, sourceLayerId);

      // Perform the clone stamp operation
      const patch = paintCloneStamp(
        destinationLayer,
        sourceLayer,
        points,
        options,
        selection,
        destWorldTransform,
        sourceWorldTransform,
      );

      // Apply the patch if there are changes
      if (patch.width > 0 && patch.height > 0) {
        const updatedDestinationLayer = {
          ...destinationLayer,
          pixelStore: destinationLayer.pixelStore.write({
            x: patch.x,
            y: patch.y,
            width: patch.width,
            height: patch.height,
            pixels: new Uint8ClampedArray(patch.pixels),
          }).store,
        };

        return {
          ...document,
          layers: document.layers.map((layer) =>
            layer.id === destinationLayerId ? updatedDestinationLayer : layer,
          ),
        };
      }

      return document;
    },
  };
}

 * edits visit one destination tile at a time, avoiding the rectangular PixelPatch
 * allocation while preserving hidden RGB and transparent-pixel semantics exactly.
 * Selection-bounded edits reuse the compact patch implementation above.
 */
export function adjustBrightnessPixelStore(
  layer: PixelLayer,
  amount: number,
  selection?: SelectionMask | null,
  worldTransform: LayerTransform = layer.transform,
): TiledPixelStore {
  validateLayer(layer);
  validateTransform(worldTransform);
  validateSelection(selection);
  if (!Number.isInteger(amount) || amount < -255 || amount > 255) {
    throw new RangeError('Brightness amount must be an integer between -255 and 255');
  }
  if (amount === 0) return layer.pixelStore;

  if (selection != null) {
    const patch = adjustBrightness(layer, amount, selection, worldTransform);
    if (patch.width === 0) return layer.pixelStore;
    return layer.pixelStore.write({ ...patch, pixels: new Uint8ClampedArray(patch.pixels) }).store;
  }

  let result = layer.pixelStore;
  const tileSize = layer.pixelStore.tileSize;
  for (let y = 0; y < layer.height; y += tileSize) {
    const height = Math.min(tileSize, layer.height - y);
    for (let x = 0; x < layer.width; x += tileSize) {
      const width = Math.min(tileSize, layer.width - x);
      const source = layer.pixelStore.read({ x, y, width, height });
      const pixels = new Uint8ClampedArray(source);
      let changed = false;
      for (let offset = 0; offset < pixels.length; offset += 4) {
        for (let channel = 0; channel < 3; channel += 1) {
          const original = source[offset + channel] ?? 0;
          const adjusted = Math.max(0, Math.min(255, original + amount));
          if (adjusted !== original) changed = true;
          pixels[offset + channel] = adjusted;
        }
      }
      if (changed) result = result.write({ x, y, width, height, pixels }).store;
    }
  }
  return result;
}

/** Applies a clone stamp stroke, sampling pixels from a source layer and writing them
 * to a destination layer. Returns the smallest layer-local patch containing changed pixels. */
export function paintCloneStamp(
  destinationLayer: PixelLayer,
  sourceLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  destinationWorldTransform: LayerTransform = destinationLayer.transform,
  sourceWorldTransform: LayerTransform = sourceLayer.transform,
): PixelPatch {
  return paintCloneStampStroke(
    destinationLayer,
    sourceLayer,
    points,
    options,
    selection,
    destinationWorldTransform,
    sourceWorldTransform,
  );
}

