function computeAlignedSourcePoint(
  destDocPoint: { x: number; y: number },
  initialSrcPoint: { x: number; y: number },
  initialDestPoint: { x: number; y: number },
  offset: { x: number; y: number } | null,
): { x: number; y: number } {
  // Calculate the offset between initial source and destination
  const baseOffsetX = destDocPoint.x - initialDestPoint.x;
  const baseOffsetY = destDocPoint.y - initialDestPoint.y;

  // Source point = source origin + offset from destination movement
  let sourceX = initialSrcPoint.x + baseOffsetX;
  let sourceY = initialSrcPoint.y + baseOffsetY;

  // Apply any additional fixed offset
  if (offset !== null) {
    sourceX += offset.x;
    sourceY += offset.y;
  }

  return { x: sourceX, y: sourceY };
}

/**
 * Computes the source document point for a given destination point in unaligned mode.
 * In unaligned mode, always samples from the original source point (plus any offset).
 */
function computeUnalignedSourcePoint(
  sourcePoint: { x: number; y: number },
  offset: { x: number; y: number } | null,
): { x: number; y: number } {
  if (offset !== null) {
    return { x: sourcePoint.x + offset.x, y: sourcePoint.y + offset.y };
  }
  return { ...sourcePoint };
}

/**
 * Samples a single pixel from the source layer at the given document-space point.
 */
function sampleSourcePixel(
  sourceLayer: PixelLayer,
  sourceDocPoint: { x: number; y: number },
  sourceWorldTransform: LayerTransform,
): [number, number, number, number] | null {
  // Convert document point to source layer-local coordinates
  const localSrc = applyInverseTransform(sourceWorldTransform, sourceDocPoint.x, sourceDocPoint.y);

  // Check bounds
  if (localSrc.x < 0 || localSrc.y < 0 || localSrc.x >= sourceLayer.width || localSrc.y >= sourceLayer.height) {
    return null;
  }

  // Sample the source pixel (nearest neighbor)
  const srcX = Math.round(localSrc.x);
  const srcY = Math.round(localSrc.y);
  const sourcePixels = sourceLayer.pixelStore.read({
    x: srcX,
    y: srcY,
    width: 1,
    height: 1,
  });

  return [
    sourcePixels[0],
    sourcePixels[1],
    sourcePixels[2],
    sourcePixels[3],
  ];
}

/**
