// ─── Clone Stamp Tests ──────────────────────────────────────────────────────

describe('paintCloneStampStroke', () => {
  const identityTransform: LayerTransform = { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 };

  function makeDocument(): ImageDocument {
    const destination = createPixelLayer({
      id: 'destination',
      name: 'Destination',
      width: 100,
      height: 100,
      pixels: new Uint8ClampedArray(100 * 100 * 4).fill(0),
    });
    const source = createPixelLayer({
      id: 'source',
      name: 'Source',
      width: 100,
      height: 100,
      pixels: new Uint8ClampedArray(100 * 100 * 4),
    });
    // Fill source with a red-to-blue gradient for easy verification
    for (let y = 0; y < 100; y++) {
      for (let x = 0; x < 100; x++) {
        const off = (y * 100 + x) * 4;
        source.pixels[off] = 255; // R
        source.pixels[off + 1] = 0; // G
        source.pixels[off + 2] = (x / 99) * 255; // B gradient
        source.pixels[off + 3] = 255; // A
      }
    }
    return createDocument({
      id: 'test-doc',
      name: 'Test Document',
      width: 100,
      height: 100,
      layers: [destination, source],
    });
  }

  it('clones a single pixel from source to destination', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const options: CloneStampOptions = {
      size: 1,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    const points = [{ x: 10, y: 10 }];
    const patch = paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
      undefined,
      identityTransform,
      identityTransform,
    );

    expect(patch.width).toBe(1);
    expect(patch.height).toBe(1);
    expect(patch.x).toBe(10);
    expect(patch.y).toBe(10);
    // Source pixel at (50,50) has B = (50/99)*255 ≈ 129
    const off = 0;
    expect(patch.pixels[off]).toBe(255); // R
    expect(patch.pixels[off + 1]).toBe(0); // G
    expect(patch.pixels[off + 2]).toBeCloseTo(129, 0); // B
    expect(patch.pixels[off + 3]).toBe(255); // A
  });

  it('respects aligned mode: maintains offset between source and destination', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const options: CloneStampOptions = {
      size: 5,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 0, y: 0 },
        sourceLayerWorldTransform: identityTransform,
        aligned: true,
        offset: null,
      },
    };

    // First dab at (10,10) → samples from (0,0)
    // Second dab at (15,10) → should sample from (5,0) in aligned mode
    const points = [
      { x: 10, y: 10 },
      { x: 15, y: 10 },
    ];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    // Check destination at (10,10) - should have source pixel from (0,0)
    const off1 = (10 * 100 + 10) * 4;
    expect(destLayer.pixels[off1]).toBe(255);
    expect(destLayer.pixels[off1 + 2]).toBe(0); // B at source (0,0)

    // Check destination at (15,10) - should have source pixel from (5,0)
    const off2 = (10 * 100 + 15) * 4;
    expect(destLayer.pixels[off2]).toBe(255);
    expect(destLayer.pixels[off2 + 2]).toBeCloseTo(13, 0); // B at source (5,0) ≈ (5/99)*255
  });

  it('respects unaligned mode: always samples from same source point', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const sourcePoint = { x: 50, y: 50 };
    const options: CloneStampOptions = {
      size: 5,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: sourcePoint,
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    const points = [
      { x: 10, y: 10 },
      { x: 20, y: 10 },
    ];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    // Both destination pixels should have same source color (from 50,50)
    const off1 = (10 * 100 + 10) * 4;
    const off2 = (10 * 100 + 20) * 4;
    expect(destLayer.pixels[off1]).toBe(255);
    expect(destLayer.pixels[off1 + 2]).toBeCloseTo(129, 0);
    expect(destLayer.pixels[off2]).toBe(255);
    expect(destLayer.pixels[off2 + 2]).toBeCloseTo(129, 0);
  });

  it('paints with brush size > 1 (broadcasts over area)', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const options: CloneStampOptions = {
      size: 10,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    const points = [{ x: 50, y: 50 }];
    const patch = paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    // Brush size 10 should paint a 10x10 area (or 9x9 depending on exact implementation)
    expect(patch.width).toBeGreaterThanOrEqual(9);
    expect(patch.height).toBeGreaterThanOrEqual(9);
    expect(patch.x).toBeLessThanOrEqual(50);
    expect(patch.y).toBeLessThanOrEqual(50);
    expect(patch.x + patch.width).toBeGreaterThanOrEqual(50);
    expect(patch.y + patch.height).toBeGreaterThanOrEqual(50);

    // All painted pixels should have the source color from (50,50)
    for (let y = patch.y; y < patch.y + patch.height; y++) {
      for (let x = patch.x; x < patch.x + patch.width; x++) {
        const off = (y * 100 + x) * 4;
        if (x < 100 && y < 100) {
          expect(destLayer.pixels[off]).toBe(255);
          expect(destLayer.pixels[off + 1]).toBe(0);
          expect(destLayer.pixels[off + 2]).toBeCloseTo(129, 0);
        }
      }
    }
  });

  it('respects opacity (partial transparency)', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    // Fill destination with white first
    for (let i = 0; i < destLayer.pixels.length; i += 4) {
      destLayer.pixels[i] = 255;
      destLayer.pixels[i + 1] = 255;
      destLayer.pixels[i + 2] = 255;
      destLayer.pixels[i + 3] = 255;
    }

    const options: CloneStampOptions = {
      size: 1,
      hardness: 1,
      opacity: 0.5,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    const points = [{ x: 10, y: 10 }];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    const off = (10 * 100 + 10) * 4;
    // With 50% opacity over white background, we should get roughly 50% of source color
    // Source (50,50) has R=255, G=0, B≈129
    // Result: R = 255*0.5 + 255*0.5 = 255, G = 0*0.5 + 255*0.5 = 127.5, B = 129*0.5 + 255*0.5 ≈ 192
    expect(destLayer.pixels[off]).toBe(255);
    expect(destLayer.pixels[off + 1]).toBeCloseTo(128, 0);
    expect(destLayer.pixels[off + 2]).toBeCloseTo(192, 0);
  });

  it('respects hardness (soft brush edges)', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const options: CloneStampOptions = {
      size: 10,
      hardness: 0.5,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    const points = [{ x: 50, y: 50 }];
    const patch = paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    // With hardness 0.5, the brush should still paint but with falloff at edges
    expect(patch.width).toBeGreaterThanOrEqual(8);
    expect(patch.height).toBeGreaterThanOrEqual(8);

    // Center pixel should be at full strength
    const centerOff = ((50 - patch.y + Math.floor(patch.height / 2)) * 100 + (50 - patch.x + Math.floor(patch.width / 2))) * 4;
    // Actually check the center of the patch
    const centerY = patch.y + Math.floor(patch.height / 2);
    const centerX = patch.x + Math.floor(patch.width / 2);
    const centerOff2 = (centerY * 100 + centerX) * 4;
    expect(destLayer.pixels[centerOff2]).toBe(255);
    expect(destLayer.pixels[centerOff2 + 3]).toBe(255);
  });

  it('supports selection clipping', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    // Create a selection that only covers a small area
    const selectionCoverage = new Uint8ClampedArray(100 * 100);
    // Fill a 20x20 rectangle at (30,30)
    for (let y = 30; y < 50; y++) {
      for (let x = 30; x < 50; x++) {
        selectionCoverage[y * 100 + x] = 255;
      }
    }

    const selection = {
      width: 100,
      height: 100,
      coverageStore: {
        read: ({ x, y, width, height }: { x: number; y: number; width: number; height: number }) => {
          const result = new Uint8ClampedArray(width * height);
          for (let dy = 0; dy < height; dy++) {
            for (let dx = 0; dx < width; dx++) {
              const ix = (y + dy) * 100 + (x + dx);
              if (ix >= 0 && ix < selectionCoverage.length) {
                result[dy * width + dx] = selectionCoverage[ix];
              }
            }
          }
          return result;
        },
      },
    };

    const options: CloneStampOptions = {
      size: 1,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    // Paint at a point inside the selection (should work)
    const points1 = [{ x: 40, y: 40 }];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points1,
      options,
      selection,
    );
    expect(destLayer.pixels[(40 * 100 + 40) * 4]).toBe(255);

    // Paint at a point outside the selection (should not work)
    const points2 = [{ x: 10, y: 10 }];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points2,
      options,
      selection,
    );
    expect(destLayer.pixels[(10 * 100 + 10) * 4]).toBe(0); // Should remain unchanged
  });

  it('handles strokes with multiple points (interpolated dabs)', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const options: CloneStampOptions = {
      size: 2,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    // A stroke from (10,10) to (20,20)
    const points = [
      { x: 10, y: 10 },
      { x: 15, y: 15 },
      { x: 20, y: 20 },
    ];
    const patch = paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    // The patch should cover the area around the stroke
    expect(patch.width).toBeGreaterThanOrEqual(8);
    expect(patch.height).toBeGreaterThanOrEqual(8);

    // Verify some painted pixels have the source color
    let paintedCount = 0;
    for (let y = patch.y; y < patch.y + patch.height; y++) {
      for (let x = patch.x; x < patch.x + patch.width; x++) {
        if (x >= 0 && x < 100 && y >= 0 && y < 100) {
          const off = (y * 100 + x) * 4;
          if (destLayer.pixels[off] !== 0) paintedCount++;
        }
      }
    }
    expect(paintedCount).toBeGreaterThan(0);
  });

  it('throws when source layer is not found', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const options: CloneStampOptions = {
      size: 1,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'nonexistent',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    expect(() =>
      paintCloneStampStroke(
        destLayer,
        srcLayer,
        [{ x: 10, y: 10 }],
        options,
      ),
    ).toThrow('Clone source layer ID is required');
  });

  it('throws when brush size is invalid', () => {
