    const points1 = [{ x: 40, y: 40 }];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points1,
      options,
      selection,
    );
    expect(destLayer.pixels[(40 * 100 + 40) * 4]).toBe(255);

    // Paint at a point outside the selection (should not work)
    const points2 = [{ x: 10, y: 10 }];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points2,
      options,
      selection,
    );
    expect(destLayer.pixels[(10 * 100 + 10) * 4]).toBe(0); // Should remain unchanged
  });

