    // The patch should cover the area around the stroke
    expect(patch.width).toBeGreaterThanOrEqual(8);
    expect(patch.height).toBeGreaterThanOrEqual(8);

    // Verify some painted pixels have the source color
    let paintedCount = 0;
    for (let y = patch.y; y < patch.y + patch.height; y++) {
      for (let x = patch.x; x < patch.x + patch.width; x++) {
