+// ─── Clone Stamp Tests ──────────────────────────────────────────────────────
+
+describe('paintCloneStampStroke', () => {
+  const identityTransform: LayerTransform = { a: 1, b: 0, c: 0, d: 1, e: 0, f: 0 };
+
+  function makeDocument(): ImageDocument {
+    const destination = createPixelLayer({
+      id: 'destination',
+      name: 'Destination',
+      width: 100,
+      height: 100,
+      pixels: new Uint8ClampedArray(100 * 100 * 4).fill(0),
+    });
+    const source = createPixelLayer({
+      id: 'source',
+      name: 'Source',
+      width: 100,
+      height: 100,
+      pixels: new Uint8ClampedArray(100 * 100 * 4),
+    });
+    // Fill source with a red-to-blue gradient for easy verification
+    for (let y = 0; y < 100; y++) {
+      for (let x = 0; x < 100; x++) {
+        const off = (y * 100 + x) * 4;
+        source.pixels[off] = 255; // R
+        source.pixels[off + 1] = 0; // G
+        source.pixels[off + 2] = (x / 99) * 255; // B gradient
+        source.pixels[off + 3] = 255; // A
+      }
+    }
+    return createDocument({
+      id: 'test-doc',
+      name: 'Test Document',
+      width: 100,
+      height: 100,
+      layers: [destination, source],
+    });
+  }
+
+  it('clones a single pixel from source to destination', () => {
+    const doc = makeDocument();
+    const destLayer = findLayer(doc, 'destination');
+    const srcLayer = findLayer(doc, 'source');
+
+    const options: CloneStampOptions = {
+      size: 1,
+      hardness: 1,
+      opacity: 1,
+      source: {
+        sourceLayerId: 'source',
+        sourcePoint: { x: 50, y: 50 },
+        sourceLayerWorldTransform: identityTransform,
+        aligned: false,
+        offset: null,
+      },
+    };
+
+    const points = [{ x: 10, y: 10 }];
+    const patch = paintCloneStampStroke(
+      destLayer,
+      srcLayer,
+      points,
+      options,
+      undefined,
+      identityTransform,
+      identityTransform,
+    );
+
+    expect(patch.width).toBe(1);
+    expect(patch.height).toBe(1);
+    expect(patch.x).toBe(10);
+    expect(patch.y).toBe(10);
+    // Source pixel at (50,50) has B = (50/99)*255 ≈ 129
+    const off = 0;
+    expect(patch.pixels[off]).toBe(255); // R
+    expect(patch.pixels[off + 1]).toBe(0); // G
+    expect(patch.pixels[off + 2]).toBeCloseTo(129, 0); // B
+    expect(patch.pixels[off + 3]).toBe(255); // A
+  });
+
+  it('respects aligned mode: maintains offset between source and destination', () => {
+    const doc = makeDocument();
+    const destLayer = findLayer(doc, 'destination');
+    const srcLayer = findLayer(doc, 'source');
+
+    const options: CloneStampOptions = {
+      size: 5,
+      hardness: 1,
+      opacity: 1,
+      source: {
+        sourceLayerId: 'source',
+        sourcePoint: { x: 0, y: 0 },
+        sourceLayerWorldTransform: identityTransform,
+        aligned: true,
+        offset: null,
+      },
+    };
+
+    // First dab at (10,10) → samples from (0,0)
+    // Second dab at (15,10) → should sample from (5,0) in aligned mode
+    const points = [
+      { x: 10, y: 10 },
+      { x: 15, y: 10 },
+    ];
+    paintCloneStampStroke(
+      destLayer,
+      srcLayer,
+      points,
+      options,
+    );
+
+    // Check destination at (10,10) - should have source pixel from (0,0)
+    const off1 = (10 * 100 + 10) * 4;
+    expect(destLayer.pixels[off1]).toBe(255);
+    expect(destLayer.pixels[off1 + 2]).toBe(0); // B at source (0,0)
+
+    // Check destination at (15,10) - should have source pixel from (5,0)
+    const off2 = (10 * 100 + 15) * 4;
+    expect(destLayer.pixels[off2]).toBe(255);
+    expect(destLayer.pixels[off2 + 2]).toBeCloseTo(13, 0); // B at source (5,0) ≈ (5/99)*255
+  });
+
+  it('respects unaligned mode: always samples from same source point', () => {
+    const doc = makeDocument();
+    const destLayer = findLayer(doc, 'destination');
