    const points = [
      { x: 10, y: 10 },
      { x: 20, y: 10 },
    ];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    // Both destination pixels should have same source color (from 50,50)
    const off1 = (10 * 100 + 10) * 4;
    const off2 = (10 * 100 + 20) * 4;
    expect(destLayer.pixels[off1]).toBe(255);
    expect(destLayer.pixels[off1 + 2]).toBeCloseTo(129, 0);
    expect(destLayer.pixels[off2]).toBe(255);
    expect(destLayer.pixels[off2 + 2]).toBeCloseTo(129, 0);
  });

  it('paints with brush size > 1 (broadcasts over area)', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const options: CloneStampOptions = {
      size: 10,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    const points = [{ x: 50, y: 50 }];
    const patch = paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    // Brush size 10 should paint a 10x10 area (or 9x9 depending on exact implementation)
    expect(patch.width).toBeGreaterThanOrEqual(9);
    expect(patch.height).toBeGreaterThanOrEqual(9);
    expect(patch.x).toBeLessThanOrEqual(50);
    expect(patch.y).toBeLessThanOrEqual(50);
    expect(patch.x + patch.width).toBeGreaterThanOrEqual(50);
    expect(patch.y + patch.height).toBeGreaterThanOrEqual(50);

    // All painted pixels should have the source color from (50,50)
    for (let y = patch.y; y < patch.y + patch.height; y++) {
      for (let x = patch.x; x < patch.x + patch.width; x++) {
        const off = (y * 100 + x) * 4;
        if (x < 100 && y < 100) {
          expect(destLayer.pixels[off]).toBe(255);
          expect(destLayer.pixels[off + 1]).toBe(0);
          expect(destLayer.pixels[off + 2]).toBeCloseTo(129, 0);
        }
      }
    }
  });

  it('respects opacity (partial transparency)', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    // Fill destination with white first
    for (let i = 0; i < destLayer.pixels.length; i += 4) {
      destLayer.pixels[i] = 255;
      destLayer.pixels[i + 1] = 255;
      destLayer.pixels[i + 2] = 255;
      destLayer.pixels[i + 3] = 255;
    }

    const options: CloneStampOptions = {
      size: 1,
      hardness: 1,
      opacity: 0.5,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    const points = [{ x: 10, y: 10 }];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    const off = (10 * 100 + 10) * 4;
    // With 50% opacity over white background, we should get roughly 50% of source color
    // Source (50,50) has R=255, G=0, B≈129
    // Result: R = 255*0.5 + 255*0.5 = 255, G = 0*0.5 + 255*0.5 = 127.5, B = 129*0.5 + 255*0.5 ≈ 192
    expect(destLayer.pixels[off]).toBe(255);
    expect(destLayer.pixels[off + 1]).toBeCloseTo(128, 0);
    expect(destLayer.pixels[off + 2]).toBeCloseTo(192, 0);
  });

  it('respects hardness (soft brush edges)', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    const options: CloneStampOptions = {
      size: 10,
      hardness: 0.5,
      opacity: 1,
      source: {
