        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    const points = [{ x: 50, y: 50 }];
    const patch = paintCloneStampStroke(
      destLayer,
      srcLayer,
      points,
      options,
    );

    // With hardness 0.5, the brush should still paint but with falloff at edges
    expect(patch.width).toBeGreaterThanOrEqual(8);
    expect(patch.height).toBeGreaterThanOrEqual(8);

    // Center pixel should be at full strength
    const centerOff = ((50 - patch.y + Math.floor(patch.height / 2)) * 100 + (50 - patch.x + Math.floor(patch.width / 2))) * 4;
    // Actually check the center of the patch
    const centerY = patch.y + Math.floor(patch.height / 2);
    const centerX = patch.x + Math.floor(patch.width / 2);
    const centerOff2 = (centerY * 100 + centerX) * 4;
    expect(destLayer.pixels[centerOff2]).toBe(255);
    expect(destLayer.pixels[centerOff2 + 3]).toBe(255);
  });

  it('supports selection clipping', () => {
    const doc = makeDocument();
    const destLayer = findLayer(doc, 'destination');
    const srcLayer = findLayer(doc, 'source');

    // Create a selection that only covers a small area
    const selectionCoverage = new Uint8ClampedArray(100 * 100);
    // Fill a 20x20 rectangle at (30,30)
    for (let y = 30; y < 50; y++) {
      for (let x = 30; x < 50; x++) {
        selectionCoverage[y * 100 + x] = 255;
      }
    }

    const selection = {
      width: 100,
      height: 100,
      coverageStore: {
        read: ({ x, y, width, height }: { x: number; y: number; width: number; height: number }) => {
          const result = new Uint8ClampedArray(width * height);
          for (let dy = 0; dy < height; dy++) {
            for (let dx = 0; dx < width; dx++) {
              const ix = (y + dy) * 100 + (x + dx);
              if (ix >= 0 && ix < selectionCoverage.length) {
                result[dy * width + dx] = selectionCoverage[ix];
              }
            }
          }
          return result;
        },
      },
    };

    const options: CloneStampOptions = {
      size: 1,
      hardness: 1,
      opacity: 1,
      source: {
        sourceLayerId: 'source',
        sourcePoint: { x: 50, y: 50 },
        sourceLayerWorldTransform: identityTransform,
        aligned: false,
        offset: null,
      },
    };

    // Paint at a point inside the selection (should work)
    const points1 = [{ x: 40, y: 40 }];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points1,
      options,
      selection,
    );
    expect(destLayer.pixels[(40 * 100 + 40) * 4]).toBe(255);

    // Paint at a point outside the selection (should not work)
    const points2 = [{ x: 10, y: 10 }];
    paintCloneStampStroke(
      destLayer,
      srcLayer,
      points2,
      options,
      selection,
    );
    expect(destLayer.pixels[(10 * 100 + 10) * 4]).toBe(0); // Should remain unchanged
  });

