/**
 * Clone stamp operations for FreetoShop.
 *
 * Implements Photoshop-style clone stamp tool that samples from a source layer
 * and paints onto a destination layer, supporting aligned/unaligned modes,
 * transformed layers, and selection clipping.
 */

import {
  createPixelLayer,
  findLayer,
  findLayerWorldTransform,
  type ImageDocument,
  type PixelLayer,
  type PixelPatch,
  type SelectionMask,
  type LayerTransform,
  type BrushPoint,
} from '@freetoshop/core-document';
import { TiledPixelStore } from '@freetoshop/pixel-storage';
import { paintStroke, type BrushOptions } from './index.js';

// ─────────────────────────────────────────────────────────────────────────────
// Type exports (mirrored from index.ts so clone-stamp.ts is self-contained)
// ─────────────────────────────────────────────────────────────────────────────

export interface CloneSource {
  readonly sourceLayerId: string;
  readonly sourcePoint: { x: number; y: number };
  readonly sourceLayerWorldTransform: LayerTransform;
  readonly aligned: boolean;
  readonly offset: { x: number; y: number } | null;
}

export interface CloneStampOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly source: CloneSource;
}

export interface CloneStampCommand {
  readonly label: string;
  readonly execute: (document: ImageDocument) => ImageDocument;
}

// ─────────────────────────────────────────────────────────────────────────────
// Geometry helpers
// ─────────────────────────────────────────────────────────────────────────────

/** Inverse of a layer transform: maps document-space → layer-local coordinates. */
function inverseTransform(transform: LayerTransform): LayerTransform {
  const det = transform.a * transform.d - transform.b * transform.c;
  if (det === 0) throw new RangeError('Layer transform must be invertible');
  return {
    a: transform.d / det,
    b: -transform.b / det,
    c: -transform.c / det,
    d: transform.a / det,
    e: (transform.c * transform.f - transform.d * transform.e) / det,
    f: (transform.b * transform.e - transform.a * transform.f) / det,
  };
}

/** Map a single document-space point through a transform to layer-local coords. */
function applyInverseTransform(
  transform: LayerTransform,
  x: number,
  y: number,
): { x: number; y: number } {
  const inv = inverseTransform(transform);
  return {
    x: inv.a * x + inv.c * y + inv.e,
    y: inv.b * x + inv.d * y + inv.f,
  };
}

/** Map a single layer-local point through a transform to document-space coords. */
function applyTransform(transform: LayerTransform, x: number, y: number): { x: number; y: number } {
  return {
    x: transform.a * x + transform.c * y + transform.e,
    y: transform.b * x + transform.d * y + transform.f,
  };
}

// ─────────────────────────────────────────────────────────────────────────────
// Aligned / unaligned source-point computation
// ─────────────────────────────────────────────────────────────────────────────

function computeAlignedSourcePoint(
  destDocPoint: { x: number; y: number },
  initialSrcPoint: { x: number; y: number },
  initialDestPoint: { x: number; y: number },
  offset: { x: number; y: number } | null,
): { x: number; y: number } {
  // Compute the offset between initial source and destination
  const dx = destDocPoint.x - initialDestPoint.x;
  const dy = destDocPoint.y - initialDestPoint.y;
  let sourceX = initialSrcPoint.x + dx;
  let sourceY = initialSrcPoint.y + dy;
  if (offset !== null) {
    sourceX += offset.x;
    sourceY += offset.y;
  }
  return { x: sourceX, y: sourceY };
}

function computeUnalignedSourcePoint(
  sourcePoint: { x: number; y: number },
  offset: { x: number; y: number } | null,
): { x: number; y: number } {
  if (offset !== null) {
    return { x: sourcePoint.x + offset.x, y: sourcePoint.y + offset.y };
  }
  return { ...sourcePoint };
}

// ─────────────────────────────────────────────────────────────────────────────
// Internal compositing + union helpers (tiny local copies)
// ─────────────────────────────────────────────────────────────────────────────

function compositeSourceOver(
  dst: Uint8ClampedArray,
  dstOffset: number,
  src: [number, number, number, number],
  alpha: number,
): void {
  const srcA = Math.max(0, Math.min(1, alpha)) * (src[3] / 255);
  if (srcA === 0) return;
  const dstA = dst[dstOffset + 3] / 255;
  const outA = srcA + dstA * (1 - srcA);
  if (outA === 0) return;
  dst[dstOffset] = Math.round((src[0] * srcA + dst[dstOffset] * dstA * (1 - srcA)) / outA);
  dst[dstOffset + 1] = Math.round((src[1] * srcA + dst[dstOffset + 1] * dstA * (1 - srcA)) / outA);
  dst[dstOffset + 2] = Math.round((src[2] * srcA + dst[dstOffset + 2] * dstA * (1 - srcA)) / outA);
  dst[dstOffset + 3] = Math.round(outA * 255);
}

function unionBounds(
  a: { left: number; top: number; right: number; bottom: number } | null,
  b: { left: number; top: number; right: number; bottom: number },
): { left: number; top: number; right: number; bottom: number } | null {
  if (a === null) return b;
  return {
    left: Math.min(a.left, b.left),
    top: Math.min(a.top, b.top),
    right: Math.max(a.right, b.right),
    bottom: Math.max(a.bottom, b.bottom),
  };
}

function emptyPatch(): PixelPatch {
  return { x: 0, y: 0, width: 0, height: 0, pixels: new Uint8ClampedArray(0) };
}

// ─────────────────────────────────────────────────────────────────────────────
// Main clone-stamp stroke function
// ─────────────────────────────────────────────────────────────────────────────

export function paintCloneStampStroke(
  destinationLayer: PixelLayer,
  sourceLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  destinationWorldTransform?: LayerTransform,
  sourceWorldTransform?: LayerTransform,
): PixelPatch {
  const destTransform =
    destinationWorldTransform ?? destinationLayer.transform;
  const srcTransform = sourceWorldTransform ?? sourceLayer.transform;

  if (!destinationLayer) throw new RangeError('Both destination and source layers are required');
  if (!sourceLayer) throw new RangeError('Both destination and source layers are required');
  if (points.length === 0) throw new RangeError('Stroke must contain at least one point');

  const { size, hardness, opacity, source } = options;
  if (!source.sourceLayerId) throw new RangeError('Clone source layer ID is required');
  if (size <= 0) throw new RangeError('Brush size must be greater than 0');
  if (hardness < 0 || hardness > 1) throw new RangeError('Hardness must be between 0 and 1');
  if (opacity < 0 || opacity > 1) throw new RangeError('Opacity must be between 0 and 1');

  const radius = size / 2;

  // Build dabs by interpolating points (same spacing logic as paintStroke)
  const spacing = Math.max(0.25, radius * 0.5);
  const dabs: { x: number; y: number; pressure: number }[] = [];
  const first = points[0];
  dabs.push({ x: first.x, y: first.y, pressure: first.pressure ?? 1 });

  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1];
    const cur = points[i];
    const dist = Math.hypot(cur.x - prev.x, cur.y - prev.y);
    const steps = Math.max(1, Math.ceil(dist / spacing));
    for (let s = 1; s <= steps; s++) {
      const t = s / steps;
      dabs.push({
        x: prev.x + (cur.x - prev.x) * t,
        y: prev.y + (cur.y - prev.y) * t,
        pressure: (prev.pressure ?? 1) + ((cur.pressure ?? 1) - (prev.pressure ?? 1)) * t,
      });
    }
  }

  // Compute the bounding box in destination layer-local space
  let bounds: { left: number; top: number; right: number; bottom: number } | null = null;
  for (const dab of dabs) {
    const local = applyInverseTransform(destTransform, dab.x, dab.y);
    const r = Math.ceil(radius);
    if (bounds === null) {
      bounds = {
        left: Math.floor(local.x - r),
        top: Math.floor(local.y - r),
        right: Math.ceil(local.x + r),
        bottom: Math.ceil(local.y + r),
      };
    } else {
      bounds.left = Math.min(bounds.left, Math.floor(local.x - r));
      bounds.top = Math.min(bounds.top, Math.floor(local.y - r));
      bounds.right = Math.max(bounds.right, Math.ceil(local.x + r));
      bounds.bottom = Math.max(bounds.bottom, Math.ceil(local.y + r));
    }
  }
  if (bounds === null) return emptyPatch();

  // Clip to layer bounds
  bounds.left = Math.max(0, bounds.left);
  bounds.top = Math.max(0, bounds.top);
  bounds.right = Math.min(destinationLayer.width - 1, bounds.right);
  bounds.bottom = Math.min(destinationLayer.height - 1, bounds.bottom);
  if (bounds.left > bounds.right || bounds.top > bounds.bottom) return emptyPatch();

  const regionW = bounds.right - bounds.left + 1;
  const regionH = bounds.bottom - bounds.top + 1;

