import {
  createAlphaChannel,
  createSelectionMask,
  type DocumentTransform,
  type ImageDocument,
  type Layer,
  type LayerTransform,
  type PathCommand,
  type PixelLayer,
  type PixelPatch,
  type RasterMask,
  type SelectionMask,
} from '@freetoshop/core-document';
import { paintCloneStampStroke, createCloneStampCommand, type CloneStampOptions, type CloneSource } from './clone-stamp.js';
export { paintCloneStampStroke, createCloneStampCommand, type CloneStampOptions, type CloneSource };
import { TiledCoverageStore, TiledPixelStore } from '@freetoshop/pixel-storage';

export type ResamplingMethod = 'nearest' | 'bilinear';

export interface ResizeImageOptions {
  readonly width: number;
  readonly height: number;
  readonly method: ResamplingMethod;
}

export interface BrushPoint {
  /** Document-space x coordinate. */
  readonly x: number;
  /** Document-space y coordinate. */
  readonly y: number;
  /** Optional normalized tablet pressure. Defaults to 1. */
  readonly pressure?: number;
}

export interface BrushOptions {
  readonly mode: 'source-over' | 'erase';
  /** Diameter in document pixels. */
  readonly size: number;
  /** Normalized hard-core radius. */
  readonly hardness: number;
  readonly opacity: number;
  readonly color: readonly [number, number, number, number];
}

export interface MaskBrushOptions {
  readonly mode: 'reveal' | 'conceal';
  /** Diameter in document pixels. A size of zero is a no-op. */
  readonly size: number;
  /** Normalized hard-core radius. */
  readonly hardness: number;
  readonly opacity: number;
}

export interface CoveragePatch {
  readonly x: number;
  readonly y: number;
  readonly width: number;
  readonly height: number;
  readonly coverage: Uint8ClampedArray;
}

export interface CloneSource {
  readonly sourceLayerId: string;
  readonly sourcePoint: { x: number; y: number };
  readonly sourceLayerWorldTransform: LayerTransform;
  readonly aligned: boolean;
  readonly offset: { x: number; y: number } | null;
}

export interface CloneStampOptions {
  readonly size: number;
  readonly hardness: number;
  readonly opacity: number;
  readonly source: CloneSource;
}

interface Bounds {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

const MAX_IMAGE_DIMENSION = 32_768;
const MAX_IMAGE_PIXELS = 100_000_000;
const MAX_RESIZE_WORKING_BYTES = 1_000_000_000;

function validateOutputSize(width: number, height: number, label = 'Image'): void {
  if (!Number.isSafeInteger(width) || width <= 0) {
    throw new RangeError(`${label} width must be a positive integer`);
  }
  if (!Number.isSafeInteger(height) || height <= 0) {
    throw new RangeError(`${label} height must be a positive integer`);
  }
  if (width > MAX_IMAGE_DIMENSION || height > MAX_IMAGE_DIMENSION) {
    throw new RangeError(`${label} dimensions cannot exceed ${String(MAX_IMAGE_DIMENSION)} pixels`);
  }
  if (!Number.isSafeInteger(width * height) || width * height > MAX_IMAGE_PIXELS) {
    throw new RangeError(`${label} area cannot exceed ${String(MAX_IMAGE_PIXELS)} pixels`);
  }
}

function validateResamplingMethod(method: string): asserts method is ResamplingMethod {
  if (method !== 'nearest' && method !== 'bilinear') {
    throw new RangeError('Resampling method must be nearest or bilinear');
  }
}

function sourceCoordinate(
  destination: number,
  sourceSize: number,
  destinationSize: number,
): number {
  return ((destination + 0.5) * sourceSize) / destinationSize - 0.5;
}

function clampIndex(value: number, size: number): number {
  return Math.max(0, Math.min(size - 1, value));
}

export function resampleCoverage(
  source: ArrayLike<number>,
  sourceWidth: number,
  sourceHeight: number,
  destinationWidth: number,
  destinationHeight: number,
  method: ResamplingMethod,
): Uint8ClampedArray {
  validateOutputSize(sourceWidth, sourceHeight, 'Source coverage');
  validateOutputSize(destinationWidth, destinationHeight, 'Destination coverage');
  if (source.length !== sourceWidth * sourceHeight) {
    throw new RangeError('Coverage buffer length does not match its dimensions');
  }
  validateResamplingMethod(method);
  const result = new Uint8ClampedArray(destinationWidth * destinationHeight);
  for (let y = 0; y < destinationHeight; y += 1) {
    const sourceY = sourceCoordinate(y, sourceHeight, destinationHeight);
    if (method === 'nearest') {
      const sampleY = clampIndex(Math.round(sourceY), sourceHeight);
      for (let x = 0; x < destinationWidth; x += 1) {
        const sampleX = clampIndex(
          Math.round(sourceCoordinate(x, sourceWidth, destinationWidth)),
          sourceWidth,
        );
        result[y * destinationWidth + x] = source[sampleY * sourceWidth + sampleX] ?? 0;
      }
      continue;
    }
    const y0 = Math.floor(sourceY);
    const y1 = y0 + 1;
    const yWeight = sourceY - y0;
    for (let x = 0; x < destinationWidth; x += 1) {
      const sourceX = sourceCoordinate(x, sourceWidth, destinationWidth);
      const x0 = Math.floor(sourceX);
      const x1 = x0 + 1;
      const xWeight = sourceX - x0;
      const sample = (sampleX: number, sampleY: number) =>
        source[
          clampIndex(sampleY, sourceHeight) * sourceWidth + clampIndex(sampleX, sourceWidth)
        ] ?? 0;
      const top = sample(x0, y0) * (1 - xWeight) + sample(x1, y0) * xWeight;
      const bottom = sample(x0, y1) * (1 - xWeight) + sample(x1, y1) * xWeight;
      result[y * destinationWidth + x] = Math.round(top * (1 - yWeight) + bottom * yWeight);
    }
  }
  return result;
}

function destinationTileKeys(
  sourceTiles: Iterable<{ x: number; y: number; width: number; height: number }>,
  sourceWidth: number,
  sourceHeight: number,
  destinationWidth: number,
  destinationHeight: number,
  destinationTileSize: number,
): number[] {
  const columnCount = Math.ceil(destinationWidth / destinationTileSize);
  const keys = new Set<number>();
  for (const tile of sourceTiles) {
    const left = Math.max(0, Math.floor((tile.x * destinationWidth) / sourceWidth) - 1);
    const top = Math.max(0, Math.floor((tile.y * destinationHeight) / sourceHeight) - 1);
    const right = Math.min(
      destinationWidth - 1,
      Math.ceil(((tile.x + tile.width) * destinationWidth) / sourceWidth) + 1,
    );
    const bottom = Math.min(
      destinationHeight - 1,
      Math.ceil(((tile.y + tile.height) * destinationHeight) / sourceHeight) + 1,
    );
    for (
      let row = Math.floor(top / destinationTileSize);
      row <= Math.floor(bottom / destinationTileSize);
      row += 1
    ) {
      for (
        let column = Math.floor(left / destinationTileSize);
        column <= Math.floor(right / destinationTileSize);
        column += 1
      ) {
        keys.add(row * columnCount + column);
      }
    }
  }
  return Array.from(keys).sort((a, b) => a - b);
}

function resampleCoverageStore(
  source: TiledCoverageStore,
  destinationWidth: number,
  destinationHeight: number,
  method: ResamplingMethod,
): TiledCoverageStore {
  validateOutputSize(destinationWidth, destinationHeight, 'Destination coverage');
  if (source.width === destinationWidth && source.height === destinationHeight && method === 'nearest') {
    return source;
  }
  const destinationTileSize = source.tileSize;
  const sourceKeys = Array.from(source.tileValues()).sort((a, b) => a - b);
  const keys = destinationTileKeys(sourceKeys, source.width, source.height, destinationWidth, destinationHeight, destinationTileSize);
  if (keys.length === 0) return TiledCoverageStore.empty(destinationWidth, destinationHeight);
  const tileSize = destinationTileSize;
  const rowCount = Math.ceil(destinationHeight / tileSize);
  const columnCount = Math.ceil(destinationWidth / tileSize);
  const result = new Array(rowCount * columnCount);
  for (let index = 0; index < result.length; index += 1) {
    result[index] = null;
  }
  const tiles: Array<{ destinationX: number; destinationY: number; sourceX: number; sourceY: number; sourceWidth: number; sourceHeight: number; destinationKey: number }> = [];
  for (const key of keys) {
    const destinationY = Math.floor(key / columnCount);
    const destinationX = key - destinationY * columnCount;
    const destinationRight = Math.min(destinationWidth, destinationX + tileSize);
    const destinationBottom = Math.min(destinationHeight, destinationY + tileSize);
    const sourceLeft = sourceCoordinate(destinationX, source.width, destinationWidth);
    const sourceTop = sourceCoordinate(destinationY, source.height, destinationHeight);
    const sourceRight = sourceCoordinate(destinationRight, source.width, destinationWidth) + 1;
    const sourceBottom = sourceCoordinate(destinationBottom, source.height, destinationHeight) + 1;
    const sourceX = Math.max(0, Math.floor(sourceLeft));
    const sourceY = Math.max(0, Math.floor(sourceTop));
    const sourceWidth = Math.min(source.width, Math.ceil(sourceRight) - sourceX);
    const sourceHeight = Math.min(source.height, Math.ceil(sourceBottom) - sourceY);
    const destinationKey = destinationY * columnCount + destinationX;
    if (sourceWidth > 0 && sourceHeight > 0) {
      tiles.push({ destinationX, destinationY, sourceX, sourceY, sourceWidth, sourceHeight, destinationKey });
    }
  }
  for (const tile of tiles) {
    const sourceRegion = source.read({
      x: tile.sourceX,
      y: tile.sourceY,
      width: tile.sourceWidth,
      height: tile.sourceHeight,
    });
    const destinationWidth = tile.destinationKey % columnCount === columnCount - 1
      ? destinationWidth - tile.destinationX
      : tileSize;
    const destinationHeight = Math.floor(tile.destinationKey / columnCount) === rowCount - 1
      ? destinationHeight - tile.destinationY
      : tileSize;
    if (destinationWidth <= 0 || destinationHeight <= 0) continue;
    const destinationRegion = new Uint8ClampedArray(destinationWidth * destinationHeight);
    for (let y = 0; y < destinationHeight; y += 1) {
      const sourceY = sourceCoordinate(tile.destinationY + y, source.height, destinationHeight);
      if (method === 'nearest') {
        const sampleY = clampIndex(Math.round(sourceY), source.height);
        for (let x = 0; x < destinationWidth; x += 1) {
          const sampleX = clampIndex(
            Math.round(sourceCoordinate(tile.destinationX + x, source.width, destinationWidth)),
            source.width,
          );
          destinationRegion[y * destinationWidth + x] = sourceRegion[sampleY * tile.sourceWidth + sampleX] ?? 0;
        }
        continue;
      }
      const y0 = Math.floor(sourceY);
      const y1 = y0 + 1;
      const yWeight = sourceY - y0;
      for (let x = 0; x < destinationWidth; x += 1) {
        const sourceX = sourceCoordinate(tile.destinationX + x, source.width, destinationWidth);
        const x0 = Math.floor(sourceX);
        const x1 = x0 + 1;
        const xWeight = sourceX - x0;
        const sample = (sampleX: number, sampleY: number) =>
          sourceRegion[
            clampIndex(sampleY, source.height) * tile.sourceWidth + clampIndex(sampleX, source.width)
          ] ?? 0;
        const top = sample(x0, y0) * (1 - xWeight) + sample(x1, y0) * xWeight;
        const bottom = sample(x0, y1) * (1 - xWeight) + sample(x1, y1) * xWeight;
        destinationRegion[y * destinationWidth + x] = Math.round(top * (1 - yWeight) + bottom * yWeight);
      }
    }
    result[tile.destinationKey] = {
      width: destinationWidth,
      height: destinationHeight,
      pixels: destinationRegion,
    };
  }
  return new TiledCoverageStore({
    width: destinationWidth,
    height: destinationHeight,
    tiles: result,
    tileSize,
  });
}

export function resamplePixelStore(
  source: TiledPixelStore,
  destinationWidth: number,
  destinationHeight: number,
  method: ResamplingMethod,
): TiledPixelStore {
  if (source.width === destinationWidth && source.height === destinationHeight && method === 'nearest') {
    return source;
  }
  const destinationTileSize = source.tileSize;
  const sourceKeys = Array.from(source.tileValues()).sort((a, b) => a - b);
  const keys = destinationTileKeys(sourceKeys, source.width, source.height, destinationWidth, destinationHeight, destinationTileSize);
  if (keys.length === 0) return TiledPixelStore.empty(destinationWidth, destinationHeight);
  const tileSize = destinationTileSize;
  const rowCount = Math.ceil(destinationHeight / tileSize);
  const columnCount = Math.ceil(destinationWidth / tileSize);
  const result = new Array(rowCount * columnCount);
  for (let index = 0; index < result.length; index += 1) {
    result[index] = null;
  }
  const tiles: Array<{ destinationX: number; destinationY: number; sourceX: number; sourceY: number; sourceWidth: number; sourceHeight: number; destinationKey: number }> = [];
  for (const key of keys) {
    const destinationY = Math.floor(key / columnCount);
    const destinationX = key - destinationY * columnCount;
    const destinationRight = Math.min(destinationWidth, destinationX + tileSize);
    const destinationBottom = Math.min(destinationHeight, destinationY + tileSize);
    const sourceLeft = sourceCoordinate(destinationX, source.width, destinationWidth);
    const sourceTop = sourceCoordinate(destinationY, source.height, destinationHeight);
    const sourceRight = sourceCoordinate(destinationRight, source.width, destinationWidth) + 1;
    const sourceBottom = sourceCoordinate(destinationBottom, source.height, destinationHeight) + 1;
    const sourceX = Math.max(0, Math.floor(sourceLeft));
    const sourceY = Math.max(0, Math.floor(sourceTop));
    const sourceWidth = Math.min(source.width, Math.ceil(sourceRight) - sourceX);
    const sourceHeight = Math.min(source.height, Math.ceil(sourceBottom) - sourceY);
    const destinationKey = destinationY * columnCount + destinationX;
    if (sourceWidth > 0 && sourceHeight > 0) {
      tiles.push({ destinationX, destinationY, sourceX, sourceY, sourceWidth, sourceHeight, destinationKey });
    }
  }
  for (const tile of tiles) {
    const sourceRegion = source.read({ x: tile.sourceX, y: tile.sourceY, width: tile.sourceWidth, height: tile.sourceHeight });
    const destinationWidth = tile.destinationKey % columnCount === columnCount - 1
      ? destinationWidth - tile.destinationX
      : tileSize;
    const destinationHeight = Math.floor(tile.destinationKey / columnCount) === rowCount - 1
      ? destinationHeight - tile.destinationY
      : tileSize;
    if (destinationWidth <= 0 || destinationHeight <= 0) continue;
    const destinationRegion = new Uint8ClampedArray(destinationWidth * destinationHeight * 4);
    for (let y = 0; y < destinationHeight; y += 1) {
      const sourceY = sourceCoordinate(tile.destinationY + y, source.height, destinationHeight);
      if (method === 'nearest') {
        const sampleY = clampIndex(Math.round(sourceY), source.height);
        for (let x = 0; x < destinationWidth; x += 1) {
          const sampleX = clampIndex(
            Math.round(sourceCoordinate(tile.destinationX + x, source.width, destinationWidth)),
            source.width,
          );
          const sourceOffset = (sampleY * tile.sourceWidth + sampleX) * 4;
          const destinationOffset = (y * destinationWidth + x) * 4;
          destinationRegion[destinationOffset] = sourceRegion[sourceOffset];
          destinationRegion[destinationOffset + 1] = sourceRegion[sourceOffset + 1];
          destinationRegion[destinationOffset + 2] = sourceRegion[sourceOffset + 2];
          destinationRegion[destinationOffset + 3] = sourceRegion[sourceOffset + 3];
        }
        continue;
      }
      const y0 = Math.floor(sourceY);
      const y1 = y0 + 1;
      const yWeight = sourceY - y0;
      for (let x = 0; x < destinationWidth; x += 1) {
        const sourceX = sourceCoordinate(tile.destinationX + x, source.width, destinationWidth);
        const x0 = Math.floor(sourceX);
        const x1 = x0 + 1;
        const xWeight = sourceX - x0;
        const sample = (sampleX: number, sampleY: number) => {
          const sourceOffset = (clampIndex(sampleY, source.height) * tile.sourceWidth + clampIndex(sampleX, source.width)) * 4;
          return [sourceRegion[sourceOffset], sourceRegion[sourceOffset + 1], sourceRegion[sourceOffset + 2], sourceRegion[sourceOffset + 3]];
        };
        const destinationOffset = (y * destinationWidth + x) * 4;
        for (let channel = 0; channel < 4; channel += 1) {
          const top = sample(x0, y0)[channel] * (1 - xWeight) + sample(x1, y0)[channel] * xWeight;
          const bottom = sample(x0, y1)[channel] * (1 - xWeight) + sample(x1, y1)[channel] * xWeight;
          destinationRegion[destinationOffset + channel] = Math.round(top * (1 - yWeight) + bottom * yWeight);
        }
      }
    }
    result[tile.destinationKey] = {
      width: destinationWidth,
      height: destinationHeight,
      pixels: destinationRegion,
    };
  }
  return new TiledPixelStore({
    width: destinationWidth,
    height: destinationHeight,
    tiles: result,
    tileSize,
  });
}

import {
  createAlphaChannel,
  createSelectionMask,
  type DocumentTransform,
  type ImageDocument,
  type Layer,
  type LayerTransform,
  type PathCommand,
  type PixelLayer,
  type PixelPatch,
  type RasterMask,
  type SelectionMask,
} from '@freetoshop/core-document';
import { paintCloneStampStroke, createCloneStampCommand, type CloneStampOptions, type CloneSource } from './clone-stamp.js';
export { paintCloneStampStroke, createCloneStampCommand, type CloneStampOptions, type CloneSource };
