  const rowCount = Math.ceil(destinationHeight / tileSize);
  const columnCount = Math.ceil(destinationWidth / tileSize);
  const result = new Array(rowCount * columnCount);
  for (let index = 0; index < result.length; index += 1) {
    result[index] = null;
  }
  const tiles: Array<{ destinationX: number; destinationY: number; sourceX: number; sourceY: number; sourceWidth: number; sourceHeight: number; destinationKey: number }> = [];
  for (const key of keys) {
    const destinationY = Math.floor(key / columnCount);
    const destinationX = key - destinationY * columnCount;
    const destinationRight = Math.min(destinationWidth, destinationX + tileSize);
    const destinationBottom = Math.min(destinationHeight, destinationY + tileSize);
    const sourceLeft = sourceCoordinate(destinationX, source.width, destinationWidth);
    const sourceTop = sourceCoordinate(destinationY, source.height, destinationHeight);
    const sourceRight = sourceCoordinate(destinationRight, source.width, destinationWidth) + 1;
    const sourceBottom = sourceCoordinate(destinationBottom, source.height, destinationHeight) + 1;
    const sourceX = Math.max(0, Math.floor(sourceLeft));
    const sourceY = Math.max(0, Math.floor(sourceTop));
    const sourceWidth = Math.min(source.width, Math.ceil(sourceRight) - sourceX);
    const sourceHeight = Math.min(source.height, Math.ceil(sourceBottom) - sourceY);
    const destinationKey = destinationY * columnCount + destinationX;
    if (sourceWidth > 0 && sourceHeight > 0) {
      tiles.push({ destinationX, destinationY, sourceX, sourceY, sourceWidth, sourceHeight, destinationKey });
    }
  }
  for (const tile of tiles) {
    const sourceRegion = source.read({ x: tile.sourceX, y: tile.sourceY, width: tile.sourceWidth, height: tile.sourceHeight });
    const destinationWidth = tile.destinationKey % columnCount === columnCount - 1
      ? destinationWidth - tile.destinationX
      : tileSize;
    const destinationHeight = Math.floor(tile.destinationKey / columnCount) === rowCount - 1
      ? destinationHeight - tile.destinationY
      : tileSize;
    if (destinationWidth <= 0 || destinationHeight <= 0) continue;
    const destinationRegion = new Uint8ClampedArray(destinationWidth * destinationHeight * 4);
    for (let y = 0; y < destinationHeight; y += 1) {
      const sourceY = sourceCoordinate(tile.destinationY + y, source.height, destinationHeight);
      if (method === 'nearest') {
        const sampleY = clampIndex(Math.round(sourceY), source.height);
        for (let x = 0; x < destinationWidth; x += 1) {
          const sampleX = clampIndex(
            Math.round(sourceCoordinate(tile.destinationX + x, source.width, destinationWidth)),
            source.width,
          );
          const sourceOffset = (sampleY * tile.sourceWidth + sampleX) * 4;
          const destinationOffset = (y * destinationWidth + x) * 4;
          destinationRegion[destinationOffset] = sourceRegion[sourceOffset];
          destinationRegion[destinationOffset + 1] = sourceRegion[sourceOffset + 1];
          destinationRegion[destinationOffset + 2] = sourceRegion[sourceOffset + 2];
          destinationRegion[destinationOffset + 3] = sourceRegion[sourceOffset + 3];
        }
        continue;
      }
      const y0 = Math.floor(sourceY);
      const y1 = y0 + 1;
      const yWeight = sourceY - y0;
      for (let x = 0; x < destinationWidth; x += 1) {
        const sourceX = sourceCoordinate(tile.destinationX + x, source.width, destinationWidth);
        const x0 = Math.floor(sourceX);
        const x1 = x0 + 1;
        const xWeight = sourceX - x0;
        const sample = (sampleX: number, sampleY: number) => {
          const sourceOffset = (clampIndex(sampleY, source.height) * tile.sourceWidth + clampIndex(sampleX, source.width)) * 4;
