          destinationRegion[destinationOffset + channel] = Math.round(top * (1 - yWeight) + bottom * yWeight);
        }
      }
    }
    result[tile.destinationKey] = {
      width: destinationWidth,
      height: destinationHeight,
      pixels: destinationRegion,
    };
  }
  return new TiledPixelStore({
    width: destinationWidth,
    height: destinationHeight,
    tiles: result,
    tileSize,
  });
}

