                           184 │       destinationHeight - 1,
                           185 │       Math.ceil(((tile.y + tile.height) * destinationHeight) / sourceHeight) + 1,
                           186 │     );
                           187 │     for (
                           188 │       let row = Math.floor(top / destinationTileSize);
                           189 │       row <= Math.floor(bottom / destinationTileSize);
                           190 │       row += 1
                           191 │     ) {
                           192 │       for (
                           193 │         let column = Math.floor(left / destinationTileSize);
                           194 │         column <= Math.floor(right / destinationTileSize);
                           195 │         column += 1
                           196 │       ) {
                           197 │         keys.add(row * columnCount + column);
                           198 │       }
                           199 │     }
                           200 │   }
                           201 │   return Array.from(keys).sort((a, b) => a - b);
                           202 │ }
                           203 │ 
                           204 │ function destinationTileRegion(
                           205 │   key: number,
                           206 │   width: number,
                           207 │   height: number,
                           208 │   tileSize: number,
                           209 │ ): { x: number; y: number; width: number; height: number } {
                           210 │   const columnCount = Math.ceil(width / tileSize);
                           211 │   const column = key % columnCount;
                           212 │   const row = Math.floor(key / columnCount);
                           213 │   const x = column * tileSize;
                           214 │   const y = row * tileSize;
                           215 │   return {
                           216 │     x,
                           217 │     y,
                           218 │     width: Math.min(tileSize, width - x),
                           219 │     height: Math.min(tileSize, height - y),
                           220 │   };
                           221 │ }
