                           223 │ function coverageStoreSample(store: TiledCoverageStore, x: number, y: number): number {
                           224 │   const sampleX = clampIndex(x, store.width);
                           225 │   const sampleY = clampIndex(y, store.height);
                           226 │   const tile = store.getTile(
                           227 │     Math.floor(sampleX / store.tileSize),
                           228 │     Math.floor(sampleY / store.tileSize),
                           229 │   );
