                           234 │ /** Resamples coverage one destination tile at a time without a source-span intermediate. */
                           235 │ export function resampleCoverageStore(
                           236 │   store: TiledCoverageStore,
                           237 │   destinationWidth: number,
                           238 │   destinationHeight: number,
                           239 │   method: ResamplingMethod,
                           240 │ ): TiledCoverageStore {
                           241 │   validateOutputSize(store.width, store.height, 'Source coverage');
                           242 │   validateOutputSize(destinationWidth, destinationHeight, 'Destination coverage');
                           243 │   validateResamplingMethod(method);
                           244 │   let result = TiledCoverageStore.uniform(
                           245 │     destinationWidth,
                           246 │     destinationHeight,
                           247 │     store.defaultCoverage,
                           248 │     store.tileSize,
                           249 │   );
                           250 │   for (const key of destinationTileKeys(
                           251 │     store.tiles(),
                           252 │     store.width,
                           253 │     store.height,
                           254 │     destinationWidth,
                           255 │     destinationHeight,
                           256 │     result.tileSize,
                           257 │   )) {
                           258 │     const region = destinationTileRegion(key, destinationWidth, destinationHeight, result.tileSize);
                           259 │     const coverage = new Uint8ClampedArray(region.width * region.height);
                           260 │     for (let y = 0; y < region.height; y += 1) {
                           261 │       const destinationY = region.y + y;
                           262 │       const sourceY = sourceCoordinate(destinationY, store.height, destinationHeight);
                           263 │       for (let x = 0; x < region.width; x += 1) {
                           264 │         const destinationX = region.x + x;
                           265 │         const sourceX = sourceCoordinate(destinationX, store.width, destinationWidth);
                           266 │         if (method === 'nearest') {
                           267 │           coverage[y * region.width + x] = coverageStoreSample(
                           268 │             store,
                           269 │             Math.round(sourceX),
                           270 │             Math.round(sourceY),
                           271 │           );
                           272 │           continue;
                           273 │         }
                           274 │         const x0 = Math.floor(sourceX);
                           275 │         const y0 = Math.floor(sourceY);
                           276 │         const xWeight = sourceX - x0;
                           277 │         const yWeight = sourceY - y0;
                           278 │         const top =
                           279 │           coverageStoreSample(store, x0, y0) * (1 - xWeight) +
                           280 │           coverageStoreSample(store, x0 + 1, y0) * xWeight;
                           281 │         const bottom =
                           282 │           coverageStoreSample(store, x0, y0 + 1) * (1 - xWeight) +
                           283 │           coverageStoreSample(store, x0 + 1, y0 + 1) * xWeight;
