                           292 │ /** Resamples straight-alpha RGBA without introducing transparent-color fringes. */
                           293 │ export function resamplePixels(
                           294 │   source: ArrayLike<number>,
                           295 │   sourceWidth: number,
                           296 │   sourceHeight: number,
                           297 │   destinationWidth: number,
                           298 │   destinationHeight: number,
                           299 │   method: ResamplingMethod,
                           300 │ ): Uint8ClampedArray {
                           301 │   validateOutputSize(sourceWidth, sourceHeight, 'Source image');
                           302 │   validateOutputSize(destinationWidth, destinationHeight, 'Destination image');
