                           304 │     throw new RangeError('Pixel buffer length does not match its dimensions');
                           305 │   }
                           306 │   validateResamplingMethod(method);
                           307 │   const result = new Uint8ClampedArray(destinationWidth * destinationHeight * 4);
                           308 │   for (let y = 0; y < destinationHeight; y += 1) {
                           309 │     const sourceY = sourceCoordinate(y, sourceHeight, destinationHeight);
                           310 │     for (let x = 0; x < destinationWidth; x += 1) {
                           311 │       const sourceX = sourceCoordinate(x, sourceWidth, destinationWidth);
                           312 │       const destinationOffset = (y * destinationWidth + x) * 4;
                           313 │       if (method === 'nearest') {
                           314 │         const sampleX = clampIndex(Math.round(sourceX), sourceWidth);
                           315 │         const sampleY = clampIndex(Math.round(sourceY), sourceHeight);
                           316 │         const sourceOffset = (sampleY * sourceWidth + sampleX) * 4;
                           317 │         for (let channel = 0; channel < 4; channel += 1) {
                           318 │           result[destinationOffset + channel] = source[sourceOffset + channel] ?? 0;
                           319 │         }
                           320 │         continue;
                           321 │       }
                           322 │       const x0 = Math.floor(sourceX);
                           323 │       const y0 = Math.floor(sourceY);
                           324 │       const xWeight = sourceX - x0;
                           325 │       const yWeight = sourceY - y0;
                           326 │       const samples = [
                           327 │         { x: x0, y: y0, weight: (1 - xWeight) * (1 - yWeight) },
                           328 │         { x: x0 + 1, y: y0, weight: xWeight * (1 - yWeight) },
                           329 │         { x: x0, y: y0 + 1, weight: (1 - xWeight) * yWeight },
                           330 │         { x: x0 + 1, y: y0 + 1, weight: xWeight * yWeight },
                           331 │       ];
                           332 │       let alpha = 0;
                           333 │       const premultiplied = [0, 0, 0];
                           334 │       for (const sample of samples) {
                           335 │         const sampleOffset =
                           336 │           (clampIndex(sample.y, sourceHeight) * sourceWidth + clampIndex(sample.x, sourceWidth)) *
                           337 │           4;
                           338 │         const sampleAlpha = (source[sampleOffset + 3] ?? 0) / 255;
                           339 │         alpha += sampleAlpha * sample.weight;
                           340 │         for (let channel = 0; channel < 3; channel += 1) {
                           341 │           premultiplied[channel] =
                           342 │             (premultiplied[channel] ?? 0) +
                           343 │             (source[sampleOffset + channel] ?? 0) * sampleAlpha * sample.weight;
                           344 │         }
                           345 │       }
                           346 │       result[destinationOffset + 3] = Math.round(alpha * 255);
                           347 │       for (let channel = 0; channel < 3; channel += 1) {
                           348 │         result[destinationOffset + channel] =
                           349 │           alpha === 0 ? 0 : Math.round((premultiplied[channel] ?? 0) / alpha);
                           350 │       }
                           351 │     }
                           352 │   }
                           353 │   return result;
                           354 │ }
