                           360 │     Math.floor(sampleX / store.tileSize),
                           361 │     Math.floor(sampleY / store.tileSize),
                           362 │   );
                           363 │   if (tile === null) return 0;
                           364 │   return tile.pixels[((sampleY - tile.y) * tile.width + sampleX - tile.x) * 4 + channel] ?? 0;
