                           391 │     for (let y = 0; y < region.height; y += 1) {
                           392 │       const sourceY = sourceCoordinate(region.y + y, store.height, destinationHeight);
                           393 │       for (let x = 0; x < region.width; x += 1) {
                           394 │         const sourceX = sourceCoordinate(region.x + x, store.width, destinationWidth);
