                           410 │       const yWeight = sourceY - y0;
                           411 │       const samples = [
                           412 │         { x: x0, y: y0, weight: (1 - xWeight) * (1 - yWeight) },
                           413 │         { x: x0 + 1, y: y0, weight: xWeight * (1 - yWeight) },
                           414 │         { x: x0, y: y0 + 1, weight: (1 - xWeight) * yWeight },
                           415 │         { x: x0 + 1, y: y0 + 1, weight: xWeight * yWeight },
