                           422 │         for (let channel = 0; channel < 3; channel += 1) {
                           423 │           premultiplied[channel] =
                           424 │             (premultiplied[channel] ?? 0) +
                           425 │             pixelStoreSample(store, sample.x, sample.y, channel) * sampleAlpha * sample.weight;
                           426 │         }
                           427 │       }
                           428 │       pixels[destinationOffset + 3] = Math.round(alpha * 255);
                           429 │       for (let channel = 0; channel < 3; channel += 1) {
                           430 │         pixels[destinationOffset + channel] =
                           431 │           alpha === 0 ? 0 : Math.round((premultiplied[channel] ?? 0) / alpha);
