                           443 │     c: left.a * right.c + left.c * right.d,
                           444 │     d: left.b * right.c + left.d * right.d,
                           445 │     e: left.a * right.e + left.c * right.f + left.e,
                           446 │     f: left.b * right.e + left.d * right.f + left.f,
                           447 │   };
                           448 │ }
