                           607 │   for (const layer of layers) {
                           608 │     if (layer.kind === 'group') {
                           609 │       bytes += estimateLayerResizeBytes(layer.children, scaleX, scaleY);
                           610 │       continue;
                           611 │     }
                           612 │     if (layer.kind === 'adjustment') {
                           613 │       if (layer.rasterMask !== null) {
                           614 │         const width = Math.max(1, Math.round(layer.rasterMask.width * scaleX));
                           615 │         const height = Math.max(1, Math.round(layer.rasterMask.height * scaleY));
                           616 │         validateOutputSize(width, height, `Layer ${layer.name} mask`);
                           617 │         bytes += width * height;
                           618 │       }
                           619 │       continue;
                           620 │     }
                           621 │     if (layer.kind === 'shape' || layer.kind === 'text' || layer.kind === 'smart-object') continue;
                           622 │     const width = Math.max(1, Math.round(layer.width * scaleX));
                           623 │     const height = Math.max(1, Math.round(layer.height * scaleY));
                           624 │     validateOutputSize(width, height, `Layer ${layer.name}`);
                           625 │     bytes += width * height * (layer.rasterMask ? 5 : 4);
                           626 │     if (!Number.isSafeInteger(bytes) || bytes > MAX_RESIZE_WORKING_BYTES) {
                           627 │       throw new RangeError(
                           628 │         `Resize working set cannot exceed ${String(MAX_RESIZE_WORKING_BYTES)} bytes`,
                           629 │       );
                           630 │     }
                           631 │   }
                           632 │   return bytes;
                           633 │ }
