/** Applies a clone stamp stroke, sampling pixels from a source layer and writing them
 * to a destination layer. Returns the smallest layer-local patch containing changed pixels. */
export function paintCloneStamp(
  destinationLayer: PixelLayer,
  sourceLayer: PixelLayer,
  points: readonly BrushPoint[],
  options: CloneStampOptions,
  selection?: SelectionMask | null,
  destinationWorldTransform: LayerTransform = destinationLayer.transform,
  sourceWorldTransform: LayerTransform = sourceLayer.transform,
): PixelPatch {
  return paintCloneStampStroke(
    destinationLayer,
    sourceLayer,
    points,
    options,
    selection,
    destinationWorldTransform,
    sourceWorldTransform,
  );
}

/** Creates a clone stamp command that can be executed as part of an undoable transaction. */
export function createCloneStampDocumentCommand(
  destinationLayerId: string,
  source: CloneSource,
  points: readonly BrushPoint[],
  options: Pick<CloneStampOptions, 'size' | 'hardness' | 'opacity'>,
  selection?: SelectionMask | null,
): { label: string; execute: (document: ImageDocument) => ImageDocument } {
  const wrapSelection = selection ?? undefined;
  return {
    label: 'Clone Stamp',
    execute: (document: ImageDocument) => {
      const destinationLayer = findLayer(document, destinationLayerId);
      if (!destinationLayer || destinationLayer.kind !== 'pixel') {
        throw new RangeError('Destination layer not found or not a pixel layer');
      }
      const sourceLayer = findLayer(document, source.sourceLayerId);
      if (!sourceLayer || sourceLayer.kind !== 'pixel') {
        throw new RangeError('Source layer not found or not a pixel layer');
      }
      const destinationWorldTransform = findLayerWorldTransform(document, destinationLayerId);
      const sourceWorldTransform = findLayerWorldTransform(document, source.sourceLayerId);
      const patch = paintCloneStampStroke(
        destinationLayer,
        sourceLayer,
        points,
        { ...options, source },
        wrapSelection,
        destinationWorldTransform,
        sourceWorldTransform,
      );
      if (patch.width === 0 && patch.height === 0) return document;
      const updatedLayer = {
        ...destinationLayer,
        pixelStore: destinationLayer.pixelStore.write({ ...patch, pixels: new Uint8ClampedArray(patch.pixels) }).store,
      };
      return {
        ...document,
        layers: document.layers.map((layer) => (layer.id === destinationLayerId ? updatedLayer : layer)),
      };
    },
  };
}

